-- UC-46: búsqueda de solicitudes de conexión sin acentos.
CREATE EXTENSION IF NOT EXISTS unaccent;

-- 
-- TABLE: actividad 
--

CREATE TABLE actividad(
    id_actividad         int8             GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    estado               varchar(50)     NOT NULL,
    nombre               varchar(100)    NOT NULL,
    duracion_minutos     int4            NOT NULL,
    fecha_hora_inicio    timestamp,
    horario_preferencia_inicio time,
    descripcion          varchar(200),
    id_planificacion     int8            NOT NULL,
    id_ubicacion         int8,
    CONSTRAINT chk_actividad_duracion CHECK (duracion_minutos > 0),
    CONSTRAINT chk_estado_actividad CHECK (estado IN ('PENDIENTE', 'EN_CURSO', 'FINALIZADA', 'CANCELADA')),
    CONSTRAINT "PK_actividad" PRIMARY KEY (id_actividad)
)
;
-- Derivacion automatica de cumplimiento de hitos y notificacion a todos los perfiles activos del proyecto
CREATE OR REPLACE FUNCTION fn_derivar_cumplimiento_hito() RETURNS trigger AS $$
DECLARE
    r_hito RECORD;
    r_destinatario RECORD;
    v_pendientes INT;
BEGIN
    -- Se dispara cuando la actividad pasa a 'FINALIZADA'
    IF NEW.estado = 'FINALIZADA' AND (OLD.estado IS NULL OR OLD.estado <> 'FINALIZADA') THEN

        FOR r_hito IN
            SELECT h.id_hito, h.id_proyecto, h.nombre AS nombre_hito
            FROM hito h
            JOIN hito_actividad ha ON h.id_hito = ha.id_hito
            WHERE ha.id_actividad = NEW.id_actividad
              AND h.estado <> 'CUMPLIDO'
        LOOP
            -- Verificar si quedan actividades sin finalizar para este hito
            SELECT COUNT(*) INTO v_pendientes
            FROM hito_actividad ha_sub
            JOIN actividad a ON ha_sub.id_actividad = a.id_actividad
            WHERE ha_sub.id_hito = r_hito.id_hito
              AND a.estado <> 'FINALIZADA';

            -- Si no quedan pendientes, el hito se marca como cumplido automaticamente
            IF v_pendientes = 0 THEN
                UPDATE hito
                SET estado = 'CUMPLIDO',
                    fecha_cumplimiento = clock_timestamp()
                WHERE id_hito = r_hito.id_hito;

                -- Notificar a todos los perfiles activos del proyecto
                FOR r_destinatario IN
                    SELECT DISTINCT per.id_perfil, per.id_usuario
                    FROM miembros_proyecto mp
                    JOIN perfil per ON mp.id_perfil = per.id_perfil
                    WHERE mp.id_proyecto = r_hito.id_proyecto
                      AND mp.estado_participacion = 'ACTIVO'
                      AND NOT EXISTS (
                          SELECT 1
                          FROM notificacion n
                          WHERE n.id_usuario_destino = per.id_usuario
                            AND n.id_perfil_contexto = per.id_perfil
                            AND n.tipo = 'HITO_CUMPLIDO'
                            AND n.entidad_tipo = 'HITO'
                            AND n.entidad_id = r_hito.id_hito
                      )
                LOOP
                    INSERT INTO notificacion (
                        id_usuario_destino,
                        id_perfil_contexto,
                        tipo,
                        mensaje,
                        entidad_tipo,
                        entidad_id,
                        leida,
                        fecha_leida,
                        origen,
                        fecha_generada
                    ) VALUES (
                        r_destinatario.id_usuario,
                        r_destinatario.id_perfil,
                        'HITO_CUMPLIDO',
                        'El hito "' || r_hito.nombre_hito || '" ha sido completado.',
                        'HITO',
                        r_hito.id_hito,
                        false,
                        NULL,
                        'TRIGGER',
                        clock_timestamp()
                    );
                END LOOP;
            END IF;
        END LOOP;
    END IF;

    RETURN NEW;
END $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_derivar_cumplimiento_hito ON actividad;
CREATE TRIGGER trg_derivar_cumplimiento_hito
    AFTER UPDATE OF estado ON actividad
    FOR EACH ROW EXECUTE FUNCTION fn_derivar_cumplimiento_hito();

-- 
-- TABLE: agenda 
--

CREATE TABLE agenda(
    id_agenda               int8     GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    margen_actividad_min    int4    DEFAULT 30 NOT NULL,
    id_usuario              int8    NOT NULL,
    CONSTRAINT chk_margen_positivo CHECK (margen_actividad_min >= 0),
    CONSTRAINT "PK_agenda" PRIMARY KEY (id_agenda)
)
;



-- 
-- TABLE: asignacion_actividad 
--

CREATE TABLE asignacion_actividad(
    id_asignacion_act     int8     GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_miembro            int8    NOT NULL,
    id_actividad          int8    NOT NULL,
    id_requerimiento_act  int8,
    CONSTRAINT "PK_asignacion_actividad" PRIMARY KEY (id_asignacion_act)
)
;
-- Notificacion de asignacion
CREATE OR REPLACE FUNCTION fn_notificar_asignacion_actividad() RETURNS trigger AS $$
DECLARE
    v_id_usuario_destino BIGINT;
    v_id_perfil_contexto BIGINT;
    v_nombre_actividad VARCHAR(100);
    v_nombre_proyecto VARCHAR(100);
BEGIN
    SELECT p.id_usuario, p.id_perfil
      INTO v_id_usuario_destino, v_id_perfil_contexto
      FROM miembros_proyecto mp
      JOIN perfil p ON p.id_perfil = mp.id_perfil
     WHERE mp.id_miembro = NEW.id_miembro;

    SELECT a.nombre, proy.nombre
      INTO v_nombre_actividad, v_nombre_proyecto
      FROM actividad a
      JOIN planificacion pl ON pl.id_planificacion = a.id_planificacion
      JOIN proyecto proy ON proy.id_proyecto = pl.id_proyecto
     WHERE a.id_actividad = NEW.id_actividad;

    IF v_id_usuario_destino IS NOT NULL
       AND NOT EXISTS (
           SELECT 1
           FROM notificacion n
           WHERE n.id_usuario_destino = v_id_usuario_destino
             AND n.id_perfil_contexto = v_id_perfil_contexto
             AND n.tipo = 'ACTIVIDAD_ASIGNADA'
             AND n.entidad_tipo = 'ACTIVIDAD'
             AND n.entidad_id = NEW.id_actividad
       ) THEN

        INSERT INTO notificacion (
            id_usuario_destino,
            id_perfil_contexto,
            tipo,
            mensaje,
            entidad_tipo,
            entidad_id,
            leida,
            fecha_leida,
            origen,
            fecha_generada
        ) VALUES (
            v_id_usuario_destino,
            v_id_perfil_contexto,
            'ACTIVIDAD_ASIGNADA',
            'Has sido asignado a la actividad "' || COALESCE(v_nombre_actividad, 'Sin Nombre') || '" en el proyecto "' || COALESCE(v_nombre_proyecto, 'Sin Nombre') || '".',
            'ACTIVIDAD',
            NEW.id_actividad,
            false,
            NULL,
            'TRIGGER',
            clock_timestamp()
        );
    END IF;

    RETURN NEW;
END $$ LANGUAGE plpgsql;


DROP TRIGGER IF EXISTS trg_notificar_asignacion_actividad ON asignacion_actividad;
CREATE TRIGGER trg_notificar_asignacion_actividad
    AFTER INSERT ON asignacion_actividad
    FOR EACH ROW EXECUTE FUNCTION fn_notificar_asignacion_actividad();

