-- 
-- TABLE: bloqueo_agenda 
--

CREATE TABLE bloqueo_agenda(
    id_bloqueo           int8             GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    fecha_hora_inicio    timestamp       NOT NULL,
    fecha_hora_fin       timestamp       NOT NULL,
    motivo               varchar(200)    NOT NULL,
    id_agenda            int8            NOT NULL,
    CONSTRAINT chk_bloqueo_rango CHECK (fecha_hora_fin > fecha_hora_inicio),
    CONSTRAINT "PK_bloqueo_agenda" PRIMARY KEY (id_bloqueo)
)
;
--Impedir solapamiento entre bloqueos manuales de la misma agenda
CREATE OR REPLACE FUNCTION fn_validar_solape_bloqueo() RETURNS trigger AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM bloqueo_agenda b
        WHERE b.id_agenda = NEW.id_agenda
          AND b.id_bloqueo IS DISTINCT FROM NEW.id_bloqueo
          AND NEW.fecha_hora_inicio < b.fecha_hora_fin
          AND NEW.fecha_hora_fin > b.fecha_hora_inicio
    ) THEN
        RAISE EXCEPTION 'El bloqueo se superpone con otro bloqueo existente de la agenda.';
    END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_bloqueo_no_solape ON bloqueo_agenda;
CREATE TRIGGER trg_bloqueo_no_solape
    BEFORE INSERT OR UPDATE ON bloqueo_agenda
    FOR EACH ROW EXECUTE FUNCTION fn_validar_solape_bloqueo();
    
-- Margen efectivo de una agenda. No hay valor hardcodeado: si la agenda no
-- tiene margen, se lee la configuracion del sistema.
CREATE OR REPLACE FUNCTION fn_margen_agenda(p_id_agenda BIGINT) RETURNS INT AS $$
DECLARE
    v_margen INT;
    v_valor VARCHAR;
BEGIN
    SELECT margen_actividad_min INTO v_margen
    FROM agenda WHERE id_agenda = p_id_agenda;

    IF v_margen IS NULL THEN
        SELECT valor INTO v_valor
        FROM configuracion_sistema
        WHERE clave = 'AGENDA_MARGEN_ACTIVIDAD_MIN';

        IF v_valor IS NULL THEN
            RAISE EXCEPTION 'Falta AGENDA_MARGEN_ACTIVIDAD_MIN en configuracion_sistema.';
        END IF;

        BEGIN
            v_margen := v_valor::INT;
        EXCEPTION WHEN invalid_text_representation THEN
            RAISE EXCEPTION 'AGENDA_MARGEN_ACTIVIDAD_MIN no es un entero válido: %', v_valor;
        END;
    END IF;

    IF v_margen < 0 THEN
        RAISE EXCEPTION 'El margen de la agenda no puede ser negativo: %', v_margen;
    END IF;

    RETURN v_margen;
END $$ LANGUAGE plpgsql;

-- Valida que un bloque de horario de una persona no se superponga con otra
-- actividad suya ni con un bloqueo manual. El margen es total entre
-- actividades: se reparte en mitades a cada lado de la actividad nueva.
CREATE OR REPLACE FUNCTION fn_validar_solape_horario_usuario(
    p_id_usuario BIGINT,
    p_id_actividad BIGINT,
    p_inicio TIMESTAMP,
    p_duracion INT,
    p_margen INT
) RETURNS void AS $$
DECLARE
    v_margen_izquierdo INT;
    v_margen_derecho INT;
    v_conflicto_id BIGINT;
    v_conflicto_nombre VARCHAR;
    v_conflicto_inicio TIMESTAMP;
    v_conflicto_fin TIMESTAMP;
    v_bloqueo_id BIGINT;
    v_bloqueo_inicio TIMESTAMP;
    v_bloqueo_fin TIMESTAMP;
BEGIN
    IF p_inicio IS NULL OR p_duracion IS NULL THEN
        RETURN;
    END IF;
    IF p_duracion <= 0 THEN
        RAISE EXCEPTION 'La duración de la actividad debe ser mayor que cero.';
    END IF;
    IF p_margen < 0 THEN
        RAISE EXCEPTION 'El margen de la agenda no puede ser negativo: %', p_margen;
    END IF;

    v_margen_izquierdo := p_margen / 2;
    v_margen_derecho := p_margen - v_margen_izquierdo;

    SELECT act.id_actividad,
           act.nombre,
           act.fecha_hora_inicio,
           act.fecha_hora_inicio + (act.duracion_minutos * INTERVAL '1 minute')
      INTO v_conflicto_id,
           v_conflicto_nombre,
           v_conflicto_inicio,
           v_conflicto_fin
      FROM asignacion_actividad aa
      JOIN actividad act ON act.id_actividad = aa.id_actividad
      JOIN planificacion pl ON pl.id_planificacion = act.id_planificacion
      JOIN proyecto p ON p.id_proyecto = pl.id_proyecto
      JOIN miembros_proyecto mp ON mp.id_miembro = aa.id_miembro
      JOIN perfil pf ON pf.id_perfil = mp.id_perfil
     WHERE p.estado IN ('PUBLICADO', 'CONFIRMADO')
       AND mp.estado_participacion = 'ACTIVO'
       AND pf.id_usuario = p_id_usuario
       AND act.id_actividad <> p_id_actividad
       AND act.fecha_hora_inicio IS NOT NULL
       AND act.estado IN ('PENDIENTE', 'EN_CURSO')
       AND (p_inicio - (v_margen_izquierdo * INTERVAL '1 minute'))
           < (act.fecha_hora_inicio + (act.duracion_minutos * INTERVAL '1 minute') + (v_margen_derecho * INTERVAL '1 minute'))
       AND (p_inicio + (p_duracion * INTERVAL '1 minute') + (v_margen_derecho * INTERVAL '1 minute'))
           > (act.fecha_hora_inicio - (v_margen_izquierdo * INTERVAL '1 minute'))
     ORDER BY act.fecha_hora_inicio
     LIMIT 1;

    IF v_conflicto_id IS NOT NULL THEN
        RAISE EXCEPTION 'El horario se superpone con otra actividad del mismo profesional (actividad %, usuario %, solicitado % a %, conflicto con actividad % "%" de % a %).',
            p_id_actividad,
            p_id_usuario,
            p_inicio,
            p_inicio + (p_duracion * INTERVAL '1 minute'),
            v_conflicto_id,
            v_conflicto_nombre,
            v_conflicto_inicio,
            v_conflicto_fin;
    END IF;

    SELECT b.id_bloqueo, b.fecha_hora_inicio, b.fecha_hora_fin
      INTO v_bloqueo_id, v_bloqueo_inicio, v_bloqueo_fin
      FROM bloqueo_agenda b
      JOIN agenda ag ON ag.id_agenda = b.id_agenda
     WHERE ag.id_usuario = p_id_usuario
       AND (p_inicio - (v_margen_izquierdo * INTERVAL '1 minute')) < b.fecha_hora_fin
       AND (p_inicio + (p_duracion * INTERVAL '1 minute') + (v_margen_derecho * INTERVAL '1 minute')) > b.fecha_hora_inicio
     ORDER BY b.fecha_hora_inicio
     LIMIT 1;

    IF v_bloqueo_id IS NOT NULL THEN
        RAISE EXCEPTION 'El horario se superpone con un bloqueo manual del profesional (actividad %, usuario %, solicitado % a %, bloqueo % de % a %).',
            p_id_actividad,
            p_id_usuario,
            p_inicio,
            p_inicio + (p_duracion * INTERVAL '1 minute'),
            v_bloqueo_id,
            v_bloqueo_inicio,
            v_bloqueo_fin;
    END IF;
END $$ LANGUAGE plpgsql;

-- Se dispara al escribir el horario de una actividad. Como la actividad puede
-- tener varios asignados, valida el calendario de cada uno.
CREATE OR REPLACE FUNCTION fn_validar_solape_actividad() RETURNS trigger AS $$
DECLARE
    r RECORD;
    v_margen INT;
BEGIN
    IF NEW.fecha_hora_inicio IS NULL OR NEW.duracion_minutos IS NULL THEN
        RETURN NEW;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM planificacion pl
        JOIN proyecto p ON p.id_proyecto = pl.id_proyecto
        WHERE pl.id_planificacion = NEW.id_planificacion
          AND p.estado = 'CONFIRMADO'
          AND pl.fecha_entrega IS NOT NULL
          AND (NEW.fecha_hora_inicio + (NEW.duracion_minutos * INTERVAL '1 minute'))
              > (pl.fecha_entrega + TIME '23:59')
    ) THEN
        RAISE EXCEPTION 'La actividad termina después de la fecha de entrega del proyecto confirmado.';
    END IF;

    FOR r IN
        SELECT DISTINCT pf.id_usuario, ag.id_agenda
        FROM asignacion_actividad aa
        JOIN miembros_proyecto mp ON mp.id_miembro = aa.id_miembro
        JOIN perfil pf ON pf.id_perfil = mp.id_perfil
        JOIN agenda ag ON ag.id_usuario = pf.id_usuario
        JOIN planificacion pl ON pl.id_planificacion = NEW.id_planificacion
        JOIN proyecto p ON p.id_proyecto = pl.id_proyecto
        WHERE aa.id_actividad = NEW.id_actividad
          AND mp.estado_participacion = 'ACTIVO'
          AND p.estado IN ('PUBLICADO', 'CONFIRMADO')
    LOOP
        v_margen := fn_margen_agenda(r.id_agenda);
        PERFORM fn_validar_solape_horario_usuario(
            r.id_usuario,
            NEW.id_actividad,
            NEW.fecha_hora_inicio,
            NEW.duracion_minutos,
            v_margen);
    END LOOP;

    RETURN NEW;
END $$ LANGUAGE plpgsql;

-- Se dispara al asignar una persona a una actividad que ya tiene horario.
CREATE OR REPLACE FUNCTION fn_validar_solape_asignacion() RETURNS trigger AS $$
DECLARE
    v_inicio TIMESTAMP;
    v_duracion INT;
    v_id_usuario BIGINT;
    v_id_agenda BIGINT;
    v_margen INT;
BEGIN
    SELECT a.fecha_hora_inicio, a.duracion_minutos
      INTO v_inicio, v_duracion
      FROM actividad a
     WHERE a.id_actividad = NEW.id_actividad;

    IF v_inicio IS NULL OR v_duracion IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT pf.id_usuario, ag.id_agenda
      INTO v_id_usuario, v_id_agenda
      FROM miembros_proyecto mp
      JOIN perfil pf ON pf.id_perfil = mp.id_perfil
      JOIN agenda ag ON ag.id_usuario = pf.id_usuario
     WHERE mp.id_miembro = NEW.id_miembro;

    IF v_id_usuario IS NULL OR v_id_agenda IS NULL THEN
        RAISE EXCEPTION 'No se encontró la agenda del profesional asignado.';
    END IF;

    v_margen := fn_margen_agenda(v_id_agenda);
    PERFORM fn_validar_solape_horario_usuario(
        v_id_usuario,
        NEW.id_actividad,
        v_inicio,
        v_duracion,
        v_margen);

    RETURN NEW;
END $$ LANGUAGE plpgsql;

-- Un usuario puede tener varios perfiles activos en el mismo proyecto, pero
-- no puede participar dos veces en la misma actividad con perfiles distintos.
CREATE OR REPLACE FUNCTION fn_validar_asignacion_unica_usuario() RETURNS trigger AS $$
DECLARE
    v_id_usuario BIGINT;
BEGIN
    SELECT pf.id_usuario
      INTO v_id_usuario
      FROM miembros_proyecto mp
      JOIN perfil pf ON pf.id_perfil = mp.id_perfil
     WHERE mp.id_miembro = NEW.id_miembro;

    IF v_id_usuario IS NULL THEN
        RETURN NEW;
    END IF;

    IF EXISTS (
        SELECT 1
          FROM asignacion_actividad aa
          JOIN miembros_proyecto mp2 ON mp2.id_miembro = aa.id_miembro
          JOIN perfil pf2 ON pf2.id_perfil = mp2.id_perfil
         WHERE aa.id_actividad = NEW.id_actividad
           AND aa.id_asignacion_act IS DISTINCT FROM NEW.id_asignacion_act
           AND pf2.id_usuario = v_id_usuario
           AND mp2.estado_participacion = 'ACTIVO'
    ) THEN
        RAISE EXCEPTION
            'ASIGNACION_DUPLICADA_USUARIO: el usuario % ya está asignado a la actividad %.',
            v_id_usuario, NEW.id_actividad
            USING ERRCODE = '23505';
    END IF;

    RETURN NEW;
END $$ LANGUAGE plpgsql;

-- Bloqueo manual: no puede insertarse, modificarse ni eliminarse si deja un
-- bloqueo cubriendo una actividad agendada.
CREATE OR REPLACE FUNCTION fn_validar_bloqueo_no_actividad() RETURNS trigger AS $$
DECLARE
    v_id_agenda BIGINT;
    v_inicio TIMESTAMP;
    v_fin TIMESTAMP;
    v_id_usuario BIGINT;
    v_margen INT;
    v_margen_izquierdo INT;
    v_margen_derecho INT;
BEGIN
    IF TG_OP = 'DELETE' THEN
        v_id_agenda := OLD.id_agenda;
        v_inicio := OLD.fecha_hora_inicio;
        v_fin := OLD.fecha_hora_fin;
    ELSE
        v_id_agenda := NEW.id_agenda;
        v_inicio := NEW.fecha_hora_inicio;
        v_fin := NEW.fecha_hora_fin;
    END IF;

    SELECT id_usuario INTO v_id_usuario
    FROM agenda WHERE id_agenda = v_id_agenda;

    v_margen := fn_margen_agenda(v_id_agenda);
    v_margen_izquierdo := v_margen / 2;
    v_margen_derecho := v_margen - v_margen_izquierdo;

    IF EXISTS (
        SELECT 1
        FROM asignacion_actividad aa
        JOIN actividad act ON act.id_actividad = aa.id_actividad
        JOIN planificacion pl ON pl.id_planificacion = act.id_planificacion
        JOIN proyecto p ON p.id_proyecto = pl.id_proyecto
        JOIN miembros_proyecto mp ON mp.id_miembro = aa.id_miembro
        JOIN perfil pf ON pf.id_perfil = mp.id_perfil
        WHERE p.estado IN ('PUBLICADO', 'CONFIRMADO')
          AND mp.estado_participacion = 'ACTIVO'
          AND pf.id_usuario = v_id_usuario
          AND act.fecha_hora_inicio IS NOT NULL
          AND act.estado IN ('PENDIENTE', 'EN_CURSO')
          AND v_inicio < (act.fecha_hora_inicio + (act.duracion_minutos * INTERVAL '1 minute') + (v_margen_derecho * INTERVAL '1 minute'))
          AND v_fin > (act.fecha_hora_inicio - (v_margen_izquierdo * INTERVAL '1 minute'))
    ) THEN
        RAISE EXCEPTION 'El bloqueo se superpone con una actividad agendada del profesional.';
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_bloqueo_no_liberar_actividad ON bloqueo_agenda;
DROP TRIGGER IF EXISTS trg_bloqueo_no_actividad ON bloqueo_agenda;
CREATE TRIGGER trg_bloqueo_no_actividad
    BEFORE INSERT OR UPDATE OR DELETE ON bloqueo_agenda
    FOR EACH ROW EXECUTE FUNCTION fn_validar_bloqueo_no_actividad();

-- 
-- TABLE: calificacion_perfil 
--

CREATE TABLE calificacion_perfil(
    id_calificacion       int8             GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_proyecto           int8             NOT NULL,
    id_perfil_emisor      int8             NOT NULL,
    id_perfil_receptor    int8             NOT NULL,
    valoracion            int4             NOT NULL,
    resenia               varchar(200)     NOT NULL,
    fecha_registro        timestamp        DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "PK_calificacion_perfil" PRIMARY KEY (id_calificacion),
    CONSTRAINT chk_calificacion_valoracion CHECK (valoracion BETWEEN 1 AND 5),
    CONSTRAINT chk_calificacion_no_autoreview CHECK (id_perfil_emisor <> id_perfil_receptor),
    CONSTRAINT chk_calificacion_resenia CHECK (btrim(resenia) <> ''),
    CONSTRAINT "UQ_calificacion_proyecto_emisor_receptor"
        UNIQUE (id_proyecto, id_perfil_emisor, id_perfil_receptor)
)
;

CREATE INDEX "IDX_calificacion_receptor"
    ON calificacion_perfil(id_perfil_receptor);

CREATE INDEX "IDX_calificacion_receptor_fecha"
    ON calificacion_perfil(id_perfil_receptor, fecha_registro DESC);

CREATE INDEX "IDX_calificacion_proyecto"
    ON calificacion_perfil(id_proyecto);

-- 
-- TABLE: caracteristica_perfil 
--

CREATE TABLE caracteristica_perfil(
    id_caracteristica_perfil    int8            GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    valor                       varchar(50),
    fecha_registro              timestamp      DEFAULT CURRENT_TIMESTAMP NOT NULL,
    id_perfil                   int8           NOT NULL,
    id_valor                    int8,
    id_caracteristica           int8           NOT NULL,
    CONSTRAINT "PK_caracteristica_perfil" PRIMARY KEY (id_caracteristica_perfil)
)
;
-- Validar que la caracteristica tecnica pertenezca a la profesion del perfil
CREATE OR REPLACE FUNCTION chk_caracteristica_tecnica_de_profesion() RETURNS trigger AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM caracteristica_tecnica ct
        JOIN perfil p ON p.id_perfil = NEW.id_perfil
        WHERE ct.id_caracteristica = NEW.id_caracteristica
          AND ct.id_profesion = p.id_profesion
    ) THEN
        RAISE EXCEPTION 'La caracteristica tecnica seleccionada no corresponde a la profesion del perfil.';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_caracteristica_tecnica_de_profesion ON caracteristica_perfil;
CREATE TRIGGER trg_caracteristica_tecnica_de_profesion
    BEFORE INSERT OR UPDATE OF id_caracteristica, id_perfil ON caracteristica_perfil
    FOR EACH ROW EXECUTE FUNCTION chk_caracteristica_tecnica_de_profesion();

-- Consistencia: valor XOR id_valor segun el tipo_dato de la caracteristica tecnica
CREATE OR REPLACE FUNCTION chk_caracteristica_perfil_valor() RETURNS trigger AS $$
DECLARE
    v_tipo_dato VARCHAR(50);
BEGIN
    SELECT tipo_dato INTO v_tipo_dato
    FROM caracteristica_tecnica
    WHERE id_caracteristica = NEW.id_caracteristica;

    IF v_tipo_dato = 'ENUMERADO' THEN
        IF NEW.id_valor IS NULL OR NEW.valor IS NOT NULL THEN
            RAISE EXCEPTION 'Para caracteristicas de tipo ENUMERADO debe especificarse id_valor y el campo valor debe ser nulo.';
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM valor_caracteristica vc
            WHERE vc.id_valor = NEW.id_valor
              AND vc.id_caracteristica = NEW.id_caracteristica
        ) THEN
            RAISE EXCEPTION 'El id_valor no pertenece a la caracteristica tecnica indicada.';
        END IF;
    ELSE -- 'TEXTO' o 'NUMERICO'
        IF NEW.valor IS NULL OR NEW.id_valor IS NOT NULL THEN
            RAISE EXCEPTION 'Para caracteristicas de tipo TEXTO o NUMERICO debe especificarse valor y id_valor debe ser nulo.';
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_caracteristica_perfil_valor ON caracteristica_perfil;
CREATE TRIGGER trg_caracteristica_perfil_valor
    BEFORE INSERT OR UPDATE OF valor, id_valor, id_caracteristica ON caracteristica_perfil
    FOR EACH ROW EXECUTE FUNCTION chk_caracteristica_perfil_valor();
    
-- valor NO negativo para caracteristicas numericas ingresadas por teclado 
CREATE OR REPLACE FUNCTION chk_caracteristica_valor_no_negativo() RETURNS trigger AS $$
DECLARE
    v_tipo_dato VARCHAR(50);
    v_numero    DOUBLE PRECISION;
BEGIN
    SELECT tipo_dato INTO v_tipo_dato
    FROM caracteristica_tecnica
    WHERE id_caracteristica = NEW.id_caracteristica;

    IF v_tipo_dato = 'NUMERICO' THEN
        IF NEW.valor IS NULL THEN
            RAISE EXCEPTION 'Para caracteristicas tecnicas de tipo NUMERICO debe proveerse un valor numerico.';
        END IF;
        BEGIN
            v_numero := NEW.valor::double precision;
        EXCEPTION WHEN invalid_text_representation THEN
            RAISE EXCEPTION 'El valor "%" no es un numero valido para la caracteristica tecnica.', NEW.valor;
        END;

        IF v_numero < 0 THEN
            RAISE EXCEPTION 'La caracteristica tecnica numerica no admite valores negativos.';
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_caracteristica_valor_no_negativo ON caracteristica_perfil;
CREATE TRIGGER trg_caracteristica_valor_no_negativo
    BEFORE INSERT OR UPDATE OF valor, id_caracteristica ON caracteristica_perfil
    FOR EACH ROW EXECUTE FUNCTION chk_caracteristica_valor_no_negativo();

-- 
-- TABLE: caracteristica_tecnica 
--

CREATE TABLE caracteristica_tecnica(
    id_caracteristica    int8             GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tipo_dato            varchar(50)     NOT NULL,
    codigo               varchar(50)     NOT NULL,
    nombre               varchar(100),
    id_profesion         int8            NOT NULL,
    id_unidad            int8,
    CONSTRAINT chk_codigo_mayus CHECK (codigo = UPPER(codigo)),
    CONSTRAINT chk_codigo_no_vacio CHECK (btrim(codigo) <> ''),
    CONSTRAINT chk_caracteristica_tecnica_tipo_dato CHECK (tipo_dato IN ('ENUMERADO', 'TEXTO', 'NUMERICO')),
    CONSTRAINT "PK_caracteristica_tecnica" PRIMARY KEY (id_caracteristica),
    CONSTRAINT chk_caract_tipo_dato_enum_id_unidad CHECK ((tipo_dato = 'ENUMERADO' AND id_unidad IS NULL) OR (tipo_dato <> 'ENUMERADO')),
    CONSTRAINT chk_unidad_solo_numerico CHECK (id_unidad IS NULL OR tipo_dato = 'NUMERICO')
)
;

-- Regla de negocio: si la caracteristica esta en uso, solo puede modificarse el nombre
CREATE OR REPLACE FUNCTION fn_caracteristica_en_uso_solo_nombre() RETURNS trigger AS $$
DECLARE
    v_en_uso BOOLEAN;
BEGIN
    -- Si fuera de 'nombre' no cambio nada, no hay nada que validar
    IF NEW.codigo = OLD.codigo
       AND NEW.tipo_dato = OLD.tipo_dato
       AND NEW.id_profesion = OLD.id_profesion
       AND NEW.id_unidad IS NOT DISTINCT FROM OLD.id_unidad THEN
        RETURN NEW;
    END IF;

    SELECT (
           EXISTS (SELECT 1 FROM caracteristica_perfil   WHERE id_caracteristica = NEW.id_caracteristica)
        OR EXISTS (SELECT 1 FROM requerimiento_act_caract WHERE id_caracteristica = NEW.id_caracteristica)
        OR EXISTS (SELECT 1 FROM requerimiento_gral_caract WHERE id_caracteristica = NEW.id_caracteristica)
    ) INTO v_en_uso;

    IF v_en_uso THEN
        RAISE EXCEPTION 'La caracteristica % esta en uso por perfiles o requerimientos; solo puede modificarse su nombre.',
            OLD.codigo
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_caracteristica_en_uso_solo_nombre ON caracteristica_tecnica;
CREATE TRIGGER trg_caracteristica_en_uso_solo_nombre
    BEFORE UPDATE ON caracteristica_tecnica
    FOR EACH ROW EXECUTE FUNCTION fn_caracteristica_en_uso_solo_nombre();

