    CONSTRAINT chk_notif_tipo_categoria CHECK (categoria IN ('CUENTA', 'PROYECTO', 'POSTULACION', 'INVITACION', 'ACTIVIDAD', 'CONTRATO', 'SOCIAL', 'ADMINISTRACION'))
