-- 
-- TABLE: perfil 
--

CREATE TABLE perfil(
    id_perfil               int8             GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_usuario              int8            NOT NULL,
    fecha_solicitud_baja    timestamp,
    estado                  varchar(50)     NOT NULL,
    nombre_artistico        varchar(50)     NOT NULL,
    biografia               varchar(200)    NOT NULL,
    id_profesion            int8            NOT NULL,
    foto_perfil             int8,
    ultima_actividad        timestamp,
    CONSTRAINT chk_perfil_nombre_artistico_len CHECK (char_length(trim(nombre_artistico)) >= 2),
    CONSTRAINT chk_perfil_biografia_len CHECK (char_length(trim(biografia)) >= 2),
    CONSTRAINT chk_perfil_estado CHECK (estado IN ('ACTIVO', 'DESHABILITADO', 'PENDIENTE_BAJA', 'BAJA')),
    CONSTRAINT "PK_perfil" PRIMARY KEY (id_perfil)
)
;
-- Unicidad de perfil activo/pendiente de baja por profesion y usuario
CREATE OR REPLACE FUNCTION chk_perfil_unico_por_profesion() RETURNS trigger AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM perfil
        WHERE id_usuario = NEW.id_usuario
          AND id_profesion = NEW.id_profesion
          AND estado IN ('ACTIVO', 'PENDIENTE_BAJA')
          AND id_perfil IS DISTINCT FROM NEW.id_perfil
    ) THEN
        RAISE EXCEPTION 'El usuario ya posee un perfil activo o en trámite de baja para la profesión indicada.';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_perfil_unico_por_profesion ON perfil;
CREATE TRIGGER trg_perfil_unico_por_profesion
    BEFORE INSERT OR UPDATE OF id_usuario, id_profesion, estado ON perfil
    FOR EACH ROW EXECUTE FUNCTION chk_perfil_unico_por_profesion();
    
-- Prohibir modificar la profesion de un perfil existente
CREATE OR REPLACE FUNCTION chk_perfil_no_cambiar_profesion() RETURNS trigger AS $$
BEGIN
    IF NEW.id_profesion IS DISTINCT FROM OLD.id_profesion THEN
        RAISE EXCEPTION 'La profesión de un perfil no puede modificarse una vez creado.';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_perfil_no_cambiar_profesion ON perfil;
CREATE TRIGGER trg_perfil_no_cambiar_profesion
    BEFORE UPDATE OF id_profesion ON perfil
    FOR EACH ROW EXECUTE FUNCTION chk_perfil_no_cambiar_profesion();
    
-- Sincronizar fecha_solicitud_baja según el estado del perfil
CREATE OR REPLACE FUNCTION chk_perfil_fecha_solicitud_baja() RETURNS trigger AS $$
BEGIN
    IF NEW.estado = 'PENDIENTE_BAJA' AND (OLD.estado IS NULL OR OLD.estado <> 'PENDIENTE_BAJA') THEN
        IF NEW.fecha_solicitud_baja IS NULL THEN
            NEW.fecha_solicitud_baja := clock_timestamp();
        END IF;
    ELSIF NEW.estado = 'ACTIVO' THEN
        NEW.fecha_solicitud_baja := NULL;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_perfil_fecha_solicitud_baja ON perfil;
CREATE TRIGGER trg_perfil_fecha_solicitud_baja
    BEFORE UPDATE OF estado ON perfil
    FOR EACH ROW EXECUTE FUNCTION chk_perfil_fecha_solicitud_baja();

--  validación usuario-perfil notificacion
CREATE OR REPLACE FUNCTION fn_validar_notificacion_perfil_contexto() RETURNS trigger AS $$
DECLARE
    v_id_usuario_perfil BIGINT;
BEGIN
    IF NEW.id_perfil_contexto IS NOT NULL THEN
        SELECT p.id_usuario INTO v_id_usuario_perfil
        FROM perfil p
        WHERE p.id_perfil = NEW.id_perfil_contexto;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'El perfil de contexto % no existe.', NEW.id_perfil_contexto
                USING ERRCODE = 'foreign_key_violation';
        END IF;

        IF v_id_usuario_perfil <> NEW.id_usuario_destino THEN
            RAISE EXCEPTION 'El perfil de contexto % no pertenece al usuario destinatario %.',
                NEW.id_perfil_contexto, NEW.id_usuario_destino
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;

    RETURN NEW;
END $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_validar_notificacion_perfil_contexto ON notificacion;

CREATE TRIGGER trg_validar_notificacion_perfil_contexto
    BEFORE INSERT OR UPDATE OF id_perfil_contexto, id_usuario_destino ON notificacion
    FOR EACH ROW EXECUTE FUNCTION fn_validar_notificacion_perfil_contexto();

