-- 
-- TABLE: proyecto 
--

CREATE TABLE proyecto(
    id_proyecto                int8             GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    fecha_inicio               timestamp,
    fecha_finalizacion         timestamp,
    fecha_cancelacion          timestamp,
    finalizacion_prematura     boolean         DEFAULT false NOT NULL,
    acepta_postulacion_gral    boolean         DEFAULT false NOT NULL,
    nombre                     varchar(50)     NOT NULL,
    descripcion                varchar(200)    NOT NULL,
    estado                     varchar(50)     NOT NULL,
    privacidad                 varchar(20)     NOT NULL,
    motivo_cancelacion         varchar(200),
    id_ubicacion               int8,
    CONSTRAINT chk_proyecto_estado CHECK (estado IN ('BORRADOR', 'PUBLICADO', 'CONFIRMADO', 'FINALIZADO', 'CANCELADO')),
    CONSTRAINT chk_proyecto_confirmado_fecha_inicio CHECK (estado <> 'CONFIRMADO' OR fecha_inicio IS NOT NULL),
    CONSTRAINT chk_proyecto_privacidad CHECK (privacidad IN ('PUBLICO', 'PRIVADO')),
    CONSTRAINT "PK_proyecto" PRIMARY KEY (id_proyecto)
)
;
-- Constraint trigger diferido. Asegura que el proyecto termine la transacción con al menos 1 director activo.
CREATE OR REPLACE FUNCTION fn_validar_proyecto_tiene_director() RETURNS trigger AS $$
DECLARE
    v_id_rol_director BIGINT;
    v_cantidad_directores INT;
BEGIN
    SELECT id_rol_proyecto INTO v_id_rol_director
    FROM rol_proyecto
    WHERE codigo = 'DIRECTOR';

    IF v_id_rol_director IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cantidad_directores
        FROM miembros_proyecto
        WHERE id_proyecto = NEW.id_proyecto
          AND id_rol_proyecto = v_id_rol_director
          AND estado_participacion = 'ACTIVO';

        IF v_cantidad_directores < 1 THEN
            RAISE EXCEPTION 'El proyecto "%" (ID %) no cuenta con directores activos. Cada proyecto debe tener al menos uno.', NEW.nombre, NEW.id_proyecto;
        END IF;
    END IF;

    RETURN NEW;
END $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_proyecto_requiere_director ON proyecto;
CREATE CONSTRAINT TRIGGER trg_proyecto_requiere_director
    AFTER INSERT OR UPDATE ON proyecto
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION fn_validar_proyecto_tiene_director();

-- Un proyecto confirmado no puede quedar con actividades pendientes sin inicio.
CREATE OR REPLACE FUNCTION fn_validar_actividades_confirmadas_con_inicio() RETURNS trigger AS $$
BEGIN
    IF NEW.estado = 'CONFIRMADO' THEN
        IF EXISTS (
            SELECT 1
            FROM actividad a
            JOIN planificacion pl ON pl.id_planificacion = a.id_planificacion
            WHERE pl.id_proyecto = NEW.id_proyecto
              AND a.estado <> 'CANCELADA'
              AND a.fecha_hora_inicio IS NULL
        ) THEN
            RAISE EXCEPTION 'El proyecto "%" (ID %) está CONFIRMADO pero tiene actividades sin fecha de inicio.', NEW.nombre, NEW.id_proyecto;
        END IF;
    END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_proyecto_confirmado_actividades_inicio ON proyecto;
CREATE CONSTRAINT TRIGGER trg_proyecto_confirmado_actividades_inicio
    AFTER INSERT OR UPDATE OF estado ON proyecto
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION fn_validar_actividades_confirmadas_con_inicio();
    
-- Operador real de la aplicación: la app setea app.id_usuario por transacción
-- con SELECT set_config('app.id_usuario', '<id>', true).
CREATE OR REPLACE FUNCTION fn_auditoria_usuario_actual() RETURNS bigint AS $$
DECLARE
    v_usuario text;
BEGIN
    v_usuario := current_setting('app.id_usuario', true);
    IF v_usuario IS NULL OR btrim(v_usuario) = '' OR v_usuario !~ '^[0-9]+$' THEN
        RETURN NULL;
    END IF;
    RETURN v_usuario::bigint;
END $$ LANGUAGE plpgsql STABLE;

-- Resuelve el código de evento contra el catálogo. Si el código no está
-- catalogado, se guarda como OTRO sin romper la operación de negocio.
CREATE OR REPLACE FUNCTION fn_evento_auditoria(p_codigo varchar)
RETURNS varchar AS $$
BEGIN
    IF p_codigo IS NULL THEN
        RETURN NULL;
    END IF;

    IF EXISTS (
        SELECT 1 FROM tipo_evento_auditoria WHERE codigo = p_codigo
    ) THEN
        RETURN p_codigo;
    END IF;

    RAISE WARNING 'Evento de auditoría no catalogado: %', p_codigo;

    IF EXISTS (
        SELECT 1 FROM tipo_evento_auditoria WHERE codigo = 'OTRO'
    ) THEN
        RETURN 'OTRO';
    END IF;

    RETURN NULL;
END $$ LANGUAGE plpgsql STABLE;

-- Auditoria sobre tabla proyecto    
CREATE OR REPLACE FUNCTION fn_auditar_cambio_proyecto() RETURNS trigger AS $$
DECLARE
    v_id_tipo_auditoria BIGINT;
    v_id_auditoria BIGINT;
    v_id_usuario BIGINT;
BEGIN
    -- Obtener id_tipo_auditoria según la acción (TG_OP en PostgreSQL es siempre 'INSERT', 'UPDATE' o 'DELETE' en mayúsculas)
    SELECT id_tipo_auditoria INTO v_id_tipo_auditoria
    FROM tipo_accion_auditoria 
    WHERE nombre = TG_OP;

    IF v_id_tipo_auditoria IS NULL THEN
        RAISE EXCEPTION 'No se encontró el tipo de acción de auditoría para la operación %', TG_OP;
    END IF;

    IF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND (OLD.estado <> NEW.estado OR OLD.privacidad <> NEW.privacidad)) THEN

        v_id_usuario := fn_auditoria_usuario_actual();

        INSERT INTO auditoria (
            usuario_bd,
            entidad_afectada,
            id_afectado,
            fecha_hora,
            ip_usuario,
            id_tipo_auditoria,
            id_usuario,
            tipo_evento,
            tipo_evento_original
        ) VALUES (
            CURRENT_USER,
            'proyecto',
            CASE WHEN TG_OP = 'DELETE' THEN OLD.id_proyecto ELSE NEW.id_proyecto END,
            clock_timestamp(),
            inet_client_addr()::varchar,
            v_id_tipo_auditoria,
            v_id_usuario,
            fn_evento_auditoria('PROYECTO_ESTADO_CAMBIADO'),
            'PROYECTO_ESTADO_CAMBIADO'
        ) RETURNING id_auditoria INTO v_id_auditoria;

        IF TG_OP = 'UPDATE' AND OLD.estado <> NEW.estado THEN
            INSERT INTO detalle_auditoria (campo, valor_anterior, valor_nuevo, id_auditoria)
            VALUES ('estado', OLD.estado, NEW.estado, v_id_auditoria);
        END IF;

        IF TG_OP = 'UPDATE' AND OLD.privacidad <> NEW.privacidad THEN
            INSERT INTO detalle_auditoria (campo, valor_anterior, valor_nuevo, id_auditoria)
            VALUES ('privacidad', OLD.privacidad, NEW.privacidad, v_id_auditoria);
        END IF;

        IF TG_OP = 'UPDATE' AND NEW.estado = 'CANCELADO'
                AND OLD.motivo_cancelacion IS DISTINCT FROM NEW.motivo_cancelacion THEN
            INSERT INTO detalle_auditoria (campo, valor_anterior, valor_nuevo, id_auditoria)
            VALUES ('motivo_cancelacion', OLD.motivo_cancelacion, NEW.motivo_cancelacion, v_id_auditoria);
        END IF;

        IF TG_OP = 'DELETE' THEN
            INSERT INTO detalle_auditoria (campo, valor_anterior, valor_nuevo, id_auditoria)
            VALUES ('registro', OLD.nombre, 'ELIMINADO', v_id_auditoria);
        END IF;
    END IF;

    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_auditar_cambio_proyecto ON proyecto;
CREATE TRIGGER trg_auditar_cambio_proyecto
    AFTER UPDATE OF estado, privacidad OR DELETE ON proyecto
    FOR EACH ROW EXECUTE FUNCTION fn_auditar_cambio_proyecto();

-- 
-- TABLE: publicacion 
--

CREATE TABLE publicacion(
    id_publicacion       int8              GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    titulo               varchar(150)     NOT NULL,
    descripcion          varchar(1000),
    fecha_publicacion    timestamp        DEFAULT CURRENT_TIMESTAMP NOT NULL,
    id_perfil            int8             NOT NULL,
    id_proyecto          int8,
    id_ubicacion         int8,
    estado               varchar(20)      DEFAULT 'ACTIVA' NOT NULL,
    CONSTRAINT chk_publicacion_titulo CHECK (char_length(trim(titulo)) > 0),
    CONSTRAINT chk_publicacion_estado CHECK (estado IN ('ACTIVA', 'OCULTA')),
    CONSTRAINT "PK_publicacion" PRIMARY KEY (id_publicacion)
)
;


-- 
-- TABLE: reporte 
--

CREATE TABLE reporte(
    id_reporte             int8            GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    entidad_tipo           varchar(20)     NOT NULL,
    entidad_id             int8            NOT NULL,
    id_usuario_autor       int8            NOT NULL,
    id_perfil_autor        int8            NOT NULL,
    id_perfil_reportado    int8,
    motivo                 varchar(30)     NOT NULL,
    descripcion            varchar(200),
    estado                 varchar(20)     DEFAULT 'PENDIENTE' NOT NULL,
    fecha_reporte          timestamp       DEFAULT CURRENT_TIMESTAMP NOT NULL,
    id_admin_revisor       int8,
    fecha_resolucion       timestamp,
    CONSTRAINT chk_reporte_entidad_tipo CHECK (entidad_tipo IN ('PERFIL', 'PUBLICACION')),
    CONSTRAINT chk_reporte_motivo CHECK (motivo IN ('SPAM', 'CONTENIDO_OFENSIVO', 'SUPLANTACION', 'PERFIL_FALSO', 'OTRO')),
    CONSTRAINT chk_reporte_estado CHECK (estado IN ('PENDIENTE', 'RESUELTO', 'DESCARTADO')),
    CONSTRAINT chk_reporte_perfil CHECK (
        (entidad_tipo = 'PERFIL' AND id_perfil_reportado IS NOT NULL AND id_perfil_reportado = entidad_id)
        OR (entidad_tipo <> 'PERFIL' AND id_perfil_reportado IS NULL)
    ),
    CONSTRAINT chk_reporte_otro CHECK (
        motivo <> 'OTRO'
        OR (descripcion IS NOT NULL AND btrim(descripcion) <> '')
    ),
    CONSTRAINT chk_reporte_resolucion CHECK (
        (estado = 'PENDIENTE' AND id_admin_revisor IS NULL AND fecha_resolucion IS NULL)
        OR (estado IN ('RESUELTO', 'DESCARTADO') AND id_admin_revisor IS NOT NULL AND fecha_resolucion IS NOT NULL)
    ),
    CONSTRAINT "PK_reporte" PRIMARY KEY (id_reporte)
)
;

-- Un autor (perfil) no puede tener dos reportes pendientes sobre la misma entidad.
CREATE UNIQUE INDEX "UQ_reporte_pendiente"
    ON reporte(id_perfil_autor, entidad_tipo, entidad_id)
    WHERE estado = 'PENDIENTE'
;

CREATE INDEX "IDX_reporte_estado_fecha"
    ON reporte(estado, fecha_reporte DESC)
;

CREATE INDEX "IDX_reporte_perfil_reportado"
    ON reporte(id_perfil_reportado)
;



-- 
-- TABLE: requerimiento_act_caract 
--

CREATE TABLE requerimiento_act_caract(
    id_req_act_caract       int8               GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_requerimiento_act    int8              NOT NULL,
    id_caracteristica       int8              NOT NULL,
    valor_min               numeric(10, 2),
    valor_max               numeric(10, 2),
    CONSTRAINT "PK_requerimiento_act_caracteristica" PRIMARY KEY (id_req_act_caract),
    CONSTRAINT "chk_valor_max_no_neg" CHECK (valor_max >= 0),
    CONSTRAINT "chk_valor_min_no_neg" CHECK (valor_min >= 0),
    CONSTRAINT "chk_req_act_caract_rango_positivo" CHECK (COALESCE(valor_min,0) >= 0 AND COALESCE(valor_max,0) >= 0),
    CONSTRAINT "chk_req_act_caract_rango" CHECK (valor_min IS NULL OR valor_max IS NULL OR valor_min <= valor_max)
)
;

CREATE OR REPLACE FUNCTION fn_req_caract_rango_solo_numerico() RETURNS trigger AS $$
DECLARE
    v_tipo_dato VARCHAR(50);
BEGIN
    SELECT tipo_dato INTO v_tipo_dato
    FROM caracteristica_tecnica
    WHERE id_caracteristica = NEW.id_caracteristica;

    IF v_tipo_dato IS NULL THEN
        RAISE EXCEPTION 'La caracteristica % no existe.', NEW.id_caracteristica
            USING ERRCODE = 'check_violation';
    END IF;

    IF v_tipo_dato <> 'NUMERICO'
       AND (NEW.valor_min IS NOT NULL OR NEW.valor_max IS NOT NULL) THEN
        RAISE EXCEPTION 'valor_min/valor_max solo aplican a caracteristicas NUMERICAS (caracteristica %, tipo %).',
            NEW.id_caracteristica, v_tipo_dato
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_req_act_caract_rango ON requerimiento_act_caract;
CREATE TRIGGER trg_req_act_caract_rango
    BEFORE INSERT OR UPDATE ON requerimiento_act_caract
    FOR EACH ROW EXECUTE FUNCTION fn_req_caract_rango_solo_numerico();


-- 
-- TABLE: requerimiento_act_caract_valor 
--

CREATE TABLE requerimiento_act_caract_valor(
    id_req_act_caract    int8    NOT NULL,
    id_caracteristica    int8    NOT NULL,
    id_valor             int8    NOT NULL,
    CONSTRAINT "PK_requerimiento_act_caract_valor" PRIMARY KEY (id_req_act_caract, id_caracteristica, id_valor)
)
;

CREATE OR REPLACE FUNCTION fn_req_caract_valor_solo_enumerado() RETURNS trigger AS $$
DECLARE
    v_id_caract_padre BIGINT;
    v_tipo_dato VARCHAR(50);
BEGIN
    IF TG_TABLE_NAME = 'requerimiento_act_caract_valor' THEN
        SELECT id_caracteristica INTO v_id_caract_padre
        FROM requerimiento_act_caract
        WHERE id_req_act_caract = NEW.id_req_act_caract;
    ELSE
        SELECT id_caracteristica INTO v_id_caract_padre
        FROM requerimiento_gral_caract
        WHERE id_req_gral_caract = NEW.id_req_gral_caract;
    END IF;

    IF v_id_caract_padre IS DISTINCT FROM NEW.id_caracteristica THEN
        RAISE EXCEPTION 'id_caracteristica no coincide con la caracteristica del requerimiento padre.'
            USING ERRCODE = 'check_violation';
    END IF;

    SELECT tipo_dato INTO v_tipo_dato
    FROM caracteristica_tecnica
    WHERE id_caracteristica = v_id_caract_padre;

    IF v_tipo_dato <> 'ENUMERADO' THEN
        RAISE EXCEPTION 'Solo caracteristicas ENUMERADAS admiten valores de catalogo en requerimientos (caracteristica %, tipo %).',
            v_id_caract_padre, v_tipo_dato
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_req_act_caract_valor ON requerimiento_act_caract_valor;
CREATE TRIGGER trg_req_act_caract_valor
    BEFORE INSERT OR UPDATE ON requerimiento_act_caract_valor
    FOR EACH ROW EXECUTE FUNCTION fn_req_caract_valor_solo_enumerado();



