        CHECK (id_perfil_remitente <> id_perfil_destinatario),
    CONSTRAINT chk_solicitud_colaboracion_fechas
        CHECK (
            (estado = 'PENDIENTE' AND fecha_respuesta IS NULL)
            OR (estado IN ('ACEPTADA', 'RECHAZADA') AND fecha_respuesta IS NOT NULL)
        )
)
;

