SELECT setval(pg_get_serial_sequence('rol_proyecto', 'id_rol_proyecto'), COALESCE(MAX(id_rol_proyecto), 1)) FROM rol_proyecto;
SELECT setval(pg_get_serial_sequence('profesion', 'id_profesion'), COALESCE(MAX(id_profesion), 1)) FROM profesion;
SELECT setval(pg_get_serial_sequence('permiso_global', 'id_permiso_global'), COALESCE(MAX(id_permiso_global), 1)) FROM permiso_global;
SELECT setval(pg_get_serial_sequence('permiso_proyecto', 'id_permiso_proyecto'), COALESCE(MAX(id_permiso_proyecto), 1)) FROM permiso_proyecto;
SELECT setval(pg_get_serial_sequence('habilidad', 'id_habilidad'), COALESCE(MAX(id_habilidad), 1)) FROM habilidad;
SELECT setval(pg_get_serial_sequence('tipo_accion_auditoria', 'id_tipo_auditoria'), COALESCE(MAX(id_tipo_auditoria), 1)) FROM tipo_accion_auditoria;
