SELECT setval(pg_get_serial_sequence('caracteristica_tecnica', 'id_caracteristica'), COALESCE(MAX(id_caracteristica), 1)) FROM caracteristica_tecnica;
SELECT setval(pg_get_serial_sequence('valor_caracteristica', 'id_valor'), COALESCE(MAX(id_valor), 1)) FROM valor_caracteristica;
SELECT setval(pg_get_serial_sequence('polaroid_perfil', 'id_polaroid'), COALESCE(MAX(id_polaroid), 1)) FROM polaroid_perfil;


--
-- VIEW: v_historial_miembros
--

CREATE OR REPLACE VIEW v_historial_miembros AS
SELECT
    mp.id_miembro,
    mp.id_proyecto,
    p.nombre AS nombre_proyecto,
    mp.id_perfil,
    pf.nombre_artistico,
    mp.id_rol_proyecto,
    rp.nombre AS nombre_rol,
    mp.id_requerimiento_gral,
    rg.descripcion AS descripcion_requerimiento,
    rg.id_profesion,
    pr.nombre AS nombre_profesion,
    mp.estado_participacion,
    mp.fecha_alta,
    mp.fecha_baja,
    mp."motivoBaja"
FROM miembros_proyecto mp
JOIN proyecto p
  ON p.id_proyecto = mp.id_proyecto
JOIN perfil pf
  ON pf.id_perfil = mp.id_perfil
JOIN rol_proyecto rp
  ON rp.id_rol_proyecto = mp.id_rol_proyecto
LEFT JOIN requerimiento_gral_proyecto rg
  ON rg.id_requerimiento_gral = mp.id_requerimiento_gral
LEFT JOIN profesion pr
  ON pr.id_profesion = rg.id_profesion
ORDER BY mp.id_proyecto, mp.id_perfil, mp.fecha_alta;

--
-- VIEW: v_historial_asignaciones_actividad
--

CREATE OR REPLACE VIEW v_historial_asignaciones_actividad AS
SELECT
    aa.id_asignacion_act,
    aa.id_actividad,
    a.nombre AS nombre_actividad,
    a.estado AS estado_actividad,
    aa.id_requerimiento_act,
    ra.descripcion AS descripcion_requerimiento,
    aa.id_miembro,
    mp.id_proyecto,
    mp.id_perfil,
    pf.nombre_artistico,
    pf.id_profesion,
    pr.nombre AS nombre_profesion,
    mp.id_rol_proyecto,
    rp.nombre AS nombre_rol,
    mp.estado_participacion,
    mp.fecha_alta AS fecha_alta_miembro,
    mp.fecha_baja AS fecha_baja_miembro,
    mp."motivoBaja" AS motivo_baja_miembro
FROM asignacion_actividad aa
JOIN actividad a
  ON a.id_actividad = aa.id_actividad
LEFT JOIN requerimiento_actividad ra
  ON ra.id_requerimiento_act = aa.id_requerimiento_act
JOIN miembros_proyecto mp
  ON mp.id_miembro = aa.id_miembro
JOIN perfil pf
  ON pf.id_perfil = mp.id_perfil
LEFT JOIN profesion pr
  ON pr.id_profesion = pf.id_profesion
JOIN rol_proyecto rp
  ON rp.id_rol_proyecto = mp.id_rol_proyecto
ORDER BY mp.id_proyecto, mp.id_perfil, aa.id_actividad;

-- ============================================================================
-- HISTORIAL INMUTABLE DE REQUERIMIENTOS Y AUTOR DE BAJA
-- ============================================================================
ALTER TABLE miembros_proyecto
    ADD CONSTRAINT "Refperfil_autor_baja_miembro"
    FOREIGN KEY (id_perfil_autor_baja)
    REFERENCES perfil(id_perfil);

CREATE INDEX "IDX_req_act_origen"
    ON requerimiento_actividad(id_requerimiento_origen);

CREATE INDEX "IDX_req_gral_origen"
    ON requerimiento_gral_proyecto(id_requerimiento_origen);

CREATE INDEX "IDX_req_act_activo"
    ON requerimiento_actividad(id_actividad)
    WHERE fecha_archivado IS NULL;

CREATE INDEX "IDX_req_gral_activo"
    ON requerimiento_gral_proyecto(id_proyecto)
    WHERE fecha_archivado IS NULL;

-- ============================================================================
-- UC-72/UC-73: BUSCADOR GLOBAL DE REQUERIMIENTOS ABIERTOS
-- ============================================================================
CREATE INDEX "IDX_req_gral_profesion_activo"
    ON requerimiento_gral_proyecto(id_profesion)
    WHERE fecha_archivado IS NULL;

CREATE INDEX "IDX_req_act_profesion_activo"
    ON requerimiento_actividad(id_profesion)
    WHERE fecha_archivado IS NULL;

CREATE INDEX "IDX_actividad_pendiente_inicio"
    ON actividad(estado, fecha_hora_inicio)
    WHERE estado = 'PENDIENTE';

CREATE INDEX "IDX_proyecto_abierto_privacidad"
    ON proyecto(estado, privacidad)
    WHERE estado IN ('PUBLICADO', 'CONFIRMADO');

-- ============================================================================
-- MÓDULO DE REEMPLAZO AUTOMÁTICO
-- ============================================================================

CREATE TABLE reemplazo(
    id_reemplazo             int8         GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tipo                     varchar(20)  NOT NULL,
    id_proyecto              int8         NOT NULL,
    id_actividad             int8,
    id_requerimiento_act     int8,
    id_requerimiento_gral    int8,
    id_miembro_baja          int8         NOT NULL,
    id_perfil_baja           int8         NOT NULL,
    origen                   varchar(30)  NOT NULL,
    estado                    varchar(40)  NOT NULL,
    fecha_creacion            timestamp    DEFAULT CURRENT_TIMESTAMP NOT NULL,
    fecha_cierre              timestamp,
    motivo_cierre             varchar(200),
    id_miembro_resultante     int8,
    id_asignacion_resultante  int8,
    CONSTRAINT pk_reemplazo PRIMARY KEY (id_reemplazo),
    CONSTRAINT chk_reemplazo_tipo CHECK (tipo IN ('ACTIVIDAD', 'GENERAL')),
    CONSTRAINT chk_reemplazo_origen CHECK (origen IN ('BAJA_VOLUNTARIA', 'ELIMINACION')),
    CONSTRAINT chk_reemplazo_estado CHECK (estado IN (
        'PENDIENTE_CONFIRMACION_DIRECTOR',
        'INVITACIONES_ENVIADAS',
        'PENDIENTE_APROBACION',
        'CUBIERTO',
        'SIN_CANDIDATOS',
        'CANCELADO',
        'EXPIRADO'
    )),
    CONSTRAINT chk_reemplazo_vacante CHECK (
        (tipo = 'ACTIVIDAD'
            AND id_actividad IS NOT NULL
            AND id_requerimiento_act IS NOT NULL
            AND id_requerimiento_gral IS NULL)
        OR
        (tipo = 'GENERAL'
            AND id_actividad IS NULL
            AND id_requerimiento_act IS NULL
            AND id_requerimiento_gral IS NOT NULL)
    )
);

ALTER TABLE reemplazo
    ADD CONSTRAINT fk_reemplazo_proyecto
    FOREIGN KEY (id_proyecto) REFERENCES proyecto(id_proyecto);
ALTER TABLE reemplazo
    ADD CONSTRAINT fk_reemplazo_actividad
    FOREIGN KEY (id_actividad) REFERENCES actividad(id_actividad);
ALTER TABLE reemplazo
    ADD CONSTRAINT fk_reemplazo_requerimiento_act
    FOREIGN KEY (id_requerimiento_act)
    REFERENCES requerimiento_actividad(id_requerimiento_act);
ALTER TABLE reemplazo
    ADD CONSTRAINT fk_reemplazo_requerimiento_gral
    FOREIGN KEY (id_requerimiento_gral)
    REFERENCES requerimiento_gral_proyecto(id_requerimiento_gral);
ALTER TABLE reemplazo
    ADD CONSTRAINT fk_reemplazo_miembro_baja
    FOREIGN KEY (id_miembro_baja) REFERENCES miembros_proyecto(id_miembro);
ALTER TABLE reemplazo
    ADD CONSTRAINT fk_reemplazo_perfil_baja
    FOREIGN KEY (id_perfil_baja) REFERENCES perfil(id_perfil);
ALTER TABLE reemplazo
    ADD CONSTRAINT fk_reemplazo_miembro_resultante
    FOREIGN KEY (id_miembro_resultante) REFERENCES miembros_proyecto(id_miembro);
ALTER TABLE reemplazo
    ADD CONSTRAINT fk_reemplazo_asignacion_resultante
    FOREIGN KEY (id_asignacion_resultante)
    REFERENCES asignacion_actividad(id_asignacion_act);

CREATE INDEX "IDX_reemplazo_proyecto"
    ON reemplazo(id_proyecto, fecha_creacion DESC);
CREATE INDEX "IDX_reemplazo_estado"
    ON reemplazo(estado);
CREATE INDEX "IDX_reemplazo_miembro_baja"
    ON reemplazo(id_miembro_baja);

CREATE TABLE reemplazo_candidato(
    id_candidato             int8         GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_reemplazo             int8         NOT NULL,
    id_proyecto              int8         NOT NULL,
    id_perfil                int8         NOT NULL,
    id_usuario               int8         NOT NULL,
    estado                   varchar(40)  NOT NULL,
    orden_ranking            int4         NOT NULL,
    puntaje                  numeric(6,2) NOT NULL,
    nivel_ubicacion          varchar(20)  NOT NULL,
    es_alternativo           boolean      DEFAULT false NOT NULL,
    detalle_faltantes        varchar(1000),
    tipo_disponibilidad      varchar(30)  NOT NULL,
    inicio_propuesto         timestamp,
    fin_propuesto            timestamp,
    mensaje                  varchar(200),
    fecha_invitacion         timestamp,
    fecha_respuesta          timestamp,
    motivo_respuesta         varchar(200),
    fecha_decision           timestamp,
    id_usuario_decision      int8,
    motivo_decision          varchar(200),
    id_miembro_creado        int8,
    id_asignacion_creada     int8,
    CONSTRAINT pk_reemplazo_candidato PRIMARY KEY (id_candidato),
    CONSTRAINT chk_reemplazo_candidato_estado CHECK (estado IN (
        'PROPUESTO',
        'INVITADO',
        'ACEPTADO_PENDIENTE_APROBACION',
        'APROBADO',
        'RECHAZADO',
        'RECHAZADO_ADMIN',
        'EXPIRADO',
        'CANCELADO'
    )),
    CONSTRAINT chk_reemplazo_candidato_puntaje CHECK (puntaje >= 0 AND puntaje <= 100),
    CONSTRAINT chk_reemplazo_candidato_ranking CHECK (orden_ranking > 0),
    CONSTRAINT chk_reemplazo_candidato_ubicacion CHECK (nivel_ubicacion IN (
        'MISMA_CIUDAD',
        'MISMA_PROVINCIA',
        'OTRA'
    )),
    CONSTRAINT chk_reemplazo_candidato_disponibilidad CHECK (tipo_disponibilidad IN (
        'EXACTA',
        'CON_REPROGRAMACION',
        'NO_APLICA',
        'NO_DISPONIBLE'
    ))
);

ALTER TABLE reemplazo_candidato
    ADD CONSTRAINT fk_reemplazo_candidato_reemplazo
    FOREIGN KEY (id_reemplazo) REFERENCES reemplazo(id_reemplazo) ON DELETE CASCADE;
ALTER TABLE reemplazo_candidato
    ADD CONSTRAINT fk_reemplazo_candidato_proyecto
    FOREIGN KEY (id_proyecto) REFERENCES proyecto(id_proyecto);
ALTER TABLE reemplazo_candidato
    ADD CONSTRAINT fk_reemplazo_candidato_perfil
    FOREIGN KEY (id_perfil) REFERENCES perfil(id_perfil);
ALTER TABLE reemplazo_candidato
    ADD CONSTRAINT fk_reemplazo_candidato_usuario
    FOREIGN KEY (id_usuario) REFERENCES usuario(id_usuario);
ALTER TABLE reemplazo_candidato
    ADD CONSTRAINT fk_reemplazo_candidato_miembro
    FOREIGN KEY (id_miembro_creado) REFERENCES miembros_proyecto(id_miembro);
ALTER TABLE reemplazo_candidato
    ADD CONSTRAINT fk_reemplazo_candidato_asignacion
    FOREIGN KEY (id_asignacion_creada)
    REFERENCES asignacion_actividad(id_asignacion_act);

CREATE UNIQUE INDEX "UQ_reemplazo_candidato_perfil"
    ON reemplazo_candidato(id_reemplazo, id_perfil);
CREATE INDEX "IDX_reemplazo_candidato_ranking"
    ON reemplazo_candidato(id_reemplazo, estado, orden_ranking);
CREATE INDEX "IDX_reemplazo_candidato_perfil_estado"
    ON reemplazo_candidato(id_perfil, estado);
CREATE INDEX "IDX_reemplazo_candidato_proyecto_estado"
    ON reemplazo_candidato(id_proyecto, estado);

-- ============================================================================

-- ============================================================================
-- BLOQUE DE CONTRATOS (UC-39 / UC-53 / UC-68)
-- Extraido de ModaLinkBD_proyecto_contratos.sql y corregido:
--   1) contrato_evento.id_contrato_version referencia la PK real de contrato_version.
--   2) las notificaciones de contrato guardan id_proyecto.
--   3) firma_contrato.rol_parte admite DIRECTOR_DESTINATARIO (varchar 30).
--   4) fecha_modificacion se actualiza ante cualquier cambio del contrato.
--   5) el evento MODIFICADO y la notificacion CONTRATO_MODIFICADO se centralizan
--      en fn_post_modificacion_contrato y no se deduplican entre modificaciones.
-- ============================================================================

-- 
-- TABLE: tipo_acuerdo_contrato 
--

CREATE TABLE tipo_acuerdo_contrato(
    id_tipo_acuerdo    int8             GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    codigo             varchar(50)      NOT NULL,
    nombre             varchar(100)     NOT NULL,
    descripcion        varchar(200),
    plantilla          text,
    activo             boolean          DEFAULT true NOT NULL,
    CONSTRAINT "UQ_tipo_acuerdo_contrato_codigo" UNIQUE (codigo),
    CONSTRAINT "PK_tipo_acuerdo_contrato" PRIMARY KEY (id_tipo_acuerdo)
)
;
-- 
-- TABLE: contrato 
--

CREATE TABLE contrato(
    id_contrato          int8             GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_proyecto          int8             NOT NULL,
    id_tipo_acuerdo      int8             NOT NULL,
    id_miembro_emisor    int8             NOT NULL,
    nombre               varchar(50)      NOT NULL,
    descripcion          varchar(200),
    texto                text,
    version_actual       int              DEFAULT 1 NOT NULL,
    fecha_creacion       timestamp        DEFAULT CURRENT_TIMESTAMP NOT NULL,
    fecha_emision        timestamp,
    fecha_modificacion   timestamp,
    fecha_cancelacion    timestamp,
    fecha_baja           timestamp,
    motivo_cancelacion   varchar(200),
    estado               varchar(50)      DEFAULT 'BORRADOR' NOT NULL,
    CONSTRAINT chk_contrato_estado CHECK (estado IN ('BORRADOR', 'PENDIENTE_FIRMA', 'ACTIVO', 'RECHAZADO_POR_PARTES', 'CANCELADO', 'ELIMINADO')),
    CONSTRAINT chk_contrato_version_positiva CHECK (version_actual > 0),
    CONSTRAINT chk_contrato_emision CHECK (
        (estado = 'BORRADOR' AND fecha_emision IS NULL)
        OR (estado IN ('PENDIENTE_FIRMA', 'ACTIVO', 'RECHAZADO_POR_PARTES', 'CANCELADO') AND fecha_emision IS NOT NULL)
        OR (estado = 'ELIMINADO')
    ),
    CONSTRAINT chk_contrato_fechas CHECK (
        (fecha_emision IS NULL OR fecha_emision >= fecha_creacion)
        AND (fecha_baja IS NULL OR fecha_baja >= fecha_creacion)
        AND (fecha_cancelacion IS NULL OR fecha_cancelacion >= fecha_creacion)
    ),
    CONSTRAINT chk_contrato_baja_estado CHECK (
        (estado = 'ELIMINADO' AND fecha_baja IS NOT NULL)
        OR (estado <> 'ELIMINADO' AND fecha_baja IS NULL)
    ),
    CONSTRAINT chk_contrato_cancelacion_estado CHECK (
        (estado = 'CANCELADO' AND fecha_cancelacion IS NOT NULL AND motivo_cancelacion IS NOT NULL AND btrim(motivo_cancelacion) <> '')
        OR (estado <> 'CANCELADO' AND fecha_cancelacion IS NULL AND motivo_cancelacion IS NULL)
    ),
    CONSTRAINT chk_contrato_texto_emitido CHECK (
        estado IN ('BORRADOR', 'ELIMINADO')
        OR (texto IS NOT NULL AND btrim(texto) <> '')
    ),
    CONSTRAINT "PK_contrato" PRIMARY KEY (id_contrato)
)
;



-- 
-- TABLE: contrato_evento 
--

CREATE TABLE contrato_evento(
    id_evento             int8             GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_contrato           int8             NOT NULL,
    id_miembro            int8,
    id_usuario            int8,
    tipo_evento           varchar(30)      NOT NULL,
    fecha_hora            timestamp        DEFAULT CURRENT_TIMESTAMP NOT NULL,
    id_contrato_version   int8,
    motivo                varchar(200),
    CONSTRAINT chk_contrato_evento_tipo CHECK (tipo_evento IN (
        'CREADO', 'MODIFICADO', 'EMITIDO', 'FIRMADO', 'RECHAZADO',
        'ACTIVADO', 'CANCELADO', 'ELIMINADO',
        'FIRMA_CANCELADA', 'FIRMA_INVALIDADA', 'MIEMBRO_BAJA'
    )),
    CONSTRAINT "PK_contrato_evento" PRIMARY KEY (id_evento)
)
;



-- 
-- TABLE: contrato_version 
--

CREATE TABLE contrato_version(
    id_contrato_version  int8             GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_contrato          int8             NOT NULL,
    version              int              NOT NULL,
    texto                text             NOT NULL,
    fecha_creacion       timestamp        DEFAULT CURRENT_TIMESTAMP NOT NULL,
    id_usuario           int8,
    CONSTRAINT chk_contrato_version_positiva CHECK (version > 0),
    CONSTRAINT "UQ_contrato_version" UNIQUE (id_contrato, version),
    CONSTRAINT "PK_contrato_version" PRIMARY KEY (id_contrato_version)
)
;
-- 
-- TABLE: firma_contrato 
--

CREATE TABLE firma_contrato(
    id_miembro            int8           NOT NULL,
    id_contrato           int8           NOT NULL,
    id_contrato_version   int8,
    rol_parte             varchar(30)    NOT NULL,
    estado_firma          varchar(20)    DEFAULT 'PENDIENTE' NOT NULL,
    fecha_firma           timestamp,
    fecha_rechazo         timestamp,
    motivo_rechazo        varchar(200),
    CONSTRAINT chk_firma_contrato_rol CHECK (rol_parte IN ('DIRECTOR', 'DESTINATARIO', 'DIRECTOR_DESTINATARIO')),
    CONSTRAINT chk_firma_contrato_estado CHECK (estado_firma IN ('PENDIENTE', 'FIRMADO', 'RECHAZADO', 'CANCELADA', 'INVALIDADA')),
    CONSTRAINT chk_firma_contrato_fechas CHECK (
        (estado_firma = 'FIRMADO' AND fecha_firma IS NOT NULL AND fecha_rechazo IS NULL AND motivo_rechazo IS NULL)
        OR (estado_firma = 'RECHAZADO' AND fecha_rechazo IS NOT NULL AND fecha_firma IS NULL AND motivo_rechazo IS NOT NULL AND btrim(motivo_rechazo) <> '')
        OR (estado_firma = 'INVALIDADA' AND fecha_firma IS NOT NULL AND fecha_rechazo IS NULL AND motivo_rechazo IS NULL)
        OR (estado_firma IN ('PENDIENTE', 'CANCELADA') AND fecha_firma IS NULL AND fecha_rechazo IS NULL AND motivo_rechazo IS NULL)
    ),
    CONSTRAINT chk_firma_contrato_version CHECK (
        (estado_firma IN ('FIRMADO', 'RECHAZADO', 'INVALIDADA') AND id_contrato_version IS NOT NULL)
        OR (estado_firma IN ('PENDIENTE', 'CANCELADA') AND id_contrato_version IS NULL)
    ),
    CONSTRAINT "PK_firma_contrato" PRIMARY KEY (id_miembro, id_contrato)
)
;

-- ============================================================================
-- FUNCIONES DE APOYO DEL MODULO DE CONTRATOS
-- ============================================================================

-- Usuario autenticado segun la variable de sesion que fija el backend.
-- Si no esta definida, devuelve NULL (util para migraciones y pruebas).
CREATE OR REPLACE FUNCTION fn_usuario_actual() RETURNS BIGINT AS $$
BEGIN
    RETURN NULLIF(current_setting('app.id_usuario', true), '')::BIGINT;
EXCEPTION WHEN others THEN
    RETURN NULL;
END;
$$ LANGUAGE plpgsql STABLE;

-- Registra un evento en la auditoria de contratos.
CREATE OR REPLACE FUNCTION fn_registrar_evento_contrato(
    p_id_contrato BIGINT,
    p_id_miembro BIGINT,
    p_id_usuario BIGINT,
    p_tipo_evento VARCHAR,
    p_id_contrato_version BIGINT,
    p_motivo VARCHAR
) RETURNS void AS $$
BEGIN
    INSERT INTO contrato_evento (
        id_contrato,
        id_miembro,
        id_usuario,
        tipo_evento,
        id_contrato_version,
        motivo
    ) VALUES (
        p_id_contrato,
        p_id_miembro,
        p_id_usuario,
        p_tipo_evento,
        p_id_contrato_version,
        p_motivo
    );
END;
$$ LANGUAGE plpgsql;

-- Inserta una notificacion para un usuario, evitando duplicados del mismo
-- tipo y contrato.
CREATE OR REPLACE FUNCTION fn_notificar_contrato_usuario(
    p_id_usuario BIGINT,
    p_id_perfil BIGINT,
    p_tipo VARCHAR,
    p_mensaje TEXT,
    p_id_contrato BIGINT
) RETURNS void AS $$
DECLARE
    v_id_proyecto BIGINT;
BEGIN
    IF p_id_usuario IS NULL THEN
        RETURN;
    END IF;

    -- El proyecto se captura al generar la notificacion para que la entidad
    -- siga siendo navegable aunque el contrato se elimine logicamente despues.
    SELECT c.id_proyecto INTO v_id_proyecto
    FROM contrato c
    WHERE c.id_contrato = p_id_contrato;

    IF NOT EXISTS (
        SELECT 1
        FROM notificacion n
        WHERE n.id_usuario_destino = p_id_usuario
          AND n.id_perfil_contexto IS NOT DISTINCT FROM p_id_perfil
          AND n.tipo = p_tipo
          AND n.entidad_tipo = 'CONTRATO'
          AND n.entidad_id = p_id_contrato
    ) THEN
        INSERT INTO notificacion (
            id_usuario_destino,
            id_perfil_contexto,
            tipo,
            mensaje,
            entidad_tipo,
            entidad_id,
            id_proyecto,
            leida,
            fecha_leida,
            origen,
            fecha_generada
        ) VALUES (
            p_id_usuario,
            p_id_perfil,
            p_tipo,
            p_mensaje,
            'CONTRATO',
            p_id_contrato,
            v_id_proyecto,
            false,
            NULL,
            'TRIGGER',
            clock_timestamp()
        );
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Notifica a todas las partes activas del contrato.
CREATE OR REPLACE FUNCTION fn_notificar_partes_contrato(
    p_id_contrato BIGINT,
    p_tipo VARCHAR,
    p_mensaje TEXT
) RETURNS void AS $$
DECLARE
    r_dest RECORD;
BEGIN
    FOR r_dest IN
        SELECT DISTINCT p.id_usuario, p.id_perfil
        FROM firma_contrato f
        JOIN miembros_proyecto mp ON mp.id_miembro = f.id_miembro
        JOIN perfil p ON p.id_perfil = mp.id_perfil
        WHERE f.id_contrato = p_id_contrato
          AND mp.estado_participacion = 'ACTIVO'
    LOOP
        PERFORM fn_notificar_contrato_usuario(
            r_dest.id_usuario,
            r_dest.id_perfil,
            p_tipo,
            p_mensaje,
            p_id_contrato
        );
    END LOOP;
END;
$$ LANGUAGE plpgsql;

-- Notifica al director activo del proyecto.
CREATE OR REPLACE FUNCTION fn_notificar_director_proyecto(
    p_id_proyecto BIGINT,
    p_tipo VARCHAR,
    p_mensaje TEXT,
    p_id_contrato BIGINT
) RETURNS void AS $$
DECLARE
    r_dest RECORD;
BEGIN
    FOR r_dest IN
        SELECT DISTINCT p.id_usuario, p.id_perfil
        FROM miembros_proyecto mp
        JOIN perfil p ON p.id_perfil = mp.id_perfil
        JOIN rol_proyecto rp ON rp.id_rol_proyecto = mp.id_rol_proyecto
        WHERE mp.id_proyecto = p_id_proyecto
          AND rp.codigo = 'DIRECTOR'
          AND mp.estado_participacion = 'ACTIVO'
    LOOP
        PERFORM fn_notificar_contrato_usuario(
            r_dest.id_usuario,
            r_dest.id_perfil,
            p_tipo,
            p_mensaje,
            p_id_contrato
        );
    END LOOP;
END;
$$ LANGUAGE plpgsql;

-- Devuelve el id_miembro del destinatario que ya tiene un contrato ACTIVO
-- del mismo tipo en el proyecto. Devuelve NULL si no hay duplicado.
CREATE OR REPLACE FUNCTION fn_contrato_tiene_duplicado_activo(
    p_id_contrato BIGINT,
    p_id_proyecto BIGINT,
    p_id_tipo_acuerdo BIGINT
) RETURNS BIGINT AS $$
DECLARE
    v_id_miembro BIGINT;
BEGIN
    SELECT f.id_miembro
      INTO v_id_miembro
      FROM firma_contrato f
     WHERE f.id_contrato = p_id_contrato
       AND f.rol_parte IN ('DESTINATARIO', 'DIRECTOR_DESTINATARIO')
       AND EXISTS (
           SELECT 1
             FROM firma_contrato f2
             JOIN contrato c2 ON c2.id_contrato = f2.id_contrato
            WHERE f2.id_miembro = f.id_miembro
              AND f2.rol_parte IN ('DESTINATARIO', 'DIRECTOR_DESTINATARIO')
              AND c2.estado = 'ACTIVO'
              AND c2.id_proyecto = p_id_proyecto
              AND c2.id_tipo_acuerdo = p_id_tipo_acuerdo
              AND c2.id_contrato <> p_id_contrato
       )
     LIMIT 1;

    RETURN v_id_miembro;
END;
$$ LANGUAGE plpgsql STABLE;

-- ============================================================================
-- VALIDACIONES DE CONTRATO
-- ============================================================================

-- Valida la creacion de un contrato. Todo contrato nace como BORRADOR.
CREATE OR REPLACE FUNCTION fn_validar_contrato_insert() RETURNS trigger AS $$
BEGIN
    IF NEW.estado <> 'BORRADOR' THEN
        RAISE EXCEPTION 'Un contrato nuevo debe crearse en estado BORRADOR.';
    END IF;

    IF NEW.fecha_emision IS NOT NULL OR NEW.fecha_baja IS NOT NULL OR NEW.fecha_cancelacion IS NOT NULL THEN
        RAISE EXCEPTION 'Un contrato nuevo no puede tener fechas de emision, baja o cancelacion.';
    END IF;

    IF NEW.version_actual <> 1 THEN
        RAISE EXCEPTION 'La version inicial de un contrato debe ser 1.';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM miembros_proyecto mp
        JOIN rol_proyecto rp ON rp.id_rol_proyecto = mp.id_rol_proyecto
        WHERE mp.id_miembro = NEW.id_miembro_emisor
          AND mp.id_proyecto = NEW.id_proyecto
          AND rp.codigo = 'DIRECTOR'
          AND mp.estado_participacion = 'ACTIVO'
    ) THEN
        RAISE EXCEPTION 'El emisor del contrato debe ser un director activo del proyecto.';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM tipo_acuerdo_contrato tac
        WHERE tac.id_tipo_acuerdo = NEW.id_tipo_acuerdo
          AND tac.activo = true
    ) THEN
        RAISE EXCEPTION 'El tipo de acuerdo % no existe o no esta activo.', NEW.id_tipo_acuerdo;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Valida y audita la modificacion de datos del contrato.
CREATE OR REPLACE FUNCTION fn_validar_contrato_editable() RETURNS trigger AS $$
DECLARE
    v_id_usuario BIGINT;
    v_hay_cambio BOOLEAN := false;
BEGIN
    v_id_usuario := fn_usuario_actual();

    IF NEW.id_proyecto <> OLD.id_proyecto THEN
        RAISE EXCEPTION 'No se puede cambiar el proyecto de un contrato.';
    END IF;

    IF NEW.id_miembro_emisor <> OLD.id_miembro_emisor THEN
        IF OLD.estado <> 'BORRADOR' THEN
            RAISE EXCEPTION 'Solo se puede cambiar el director emisor mientras el contrato esta en BORRADOR.';
        END IF;

        IF NOT EXISTS (
            SELECT 1
            FROM miembros_proyecto mp
            JOIN rol_proyecto rp ON rp.id_rol_proyecto = mp.id_rol_proyecto
            WHERE mp.id_miembro = NEW.id_miembro_emisor
              AND mp.id_proyecto = NEW.id_proyecto
              AND rp.codigo = 'DIRECTOR'
              AND mp.estado_participacion = 'ACTIVO'
        ) THEN
            RAISE EXCEPTION 'El nuevo emisor debe ser un director activo del proyecto.';
        END IF;

        v_hay_cambio := true;
    END IF;

    IF NEW.id_tipo_acuerdo <> OLD.id_tipo_acuerdo THEN
        IF NOT EXISTS (
            SELECT 1 FROM tipo_acuerdo_contrato
            WHERE id_tipo_acuerdo = NEW.id_tipo_acuerdo AND activo = true
        ) THEN
            RAISE EXCEPTION 'El tipo de acuerdo % no existe o no esta activo.', NEW.id_tipo_acuerdo;
        END IF;
        v_hay_cambio := true;
    END IF;

    IF NEW.nombre <> OLD.nombre OR NEW.descripcion IS DISTINCT FROM OLD.descripcion THEN
        v_hay_cambio := true;
    END IF;

    IF NEW.texto IS DISTINCT FROM OLD.texto THEN
        v_hay_cambio := true;

        IF OLD.estado NOT IN ('BORRADOR', 'PENDIENTE_FIRMA') THEN
            RAISE EXCEPTION 'Solo se puede modificar el texto de un contrato en BORRADOR o PENDIENTE_FIRMA.';
        END IF;

        IF EXISTS (
            SELECT 1 FROM firma_contrato
            WHERE id_contrato = OLD.id_contrato
              AND estado_firma IN ('FIRMADO', 'RECHAZADO', 'INVALIDADA')
        ) THEN
            RAISE EXCEPTION 'No se puede modificar un contrato con firmas registradas.';
        END IF;

        IF NEW.texto IS NOT NULL AND btrim(NEW.texto) <> '' THEN
            IF OLD.texto IS NULL THEN
                INSERT INTO contrato_version (id_contrato, version, texto, id_usuario)
                VALUES (OLD.id_contrato, NEW.version_actual, NEW.texto, v_id_usuario)
                ON CONFLICT (id_contrato, version) DO NOTHING;
            ELSE
                NEW.version_actual := OLD.version_actual + 1;

                INSERT INTO contrato_version (id_contrato, version, texto, id_usuario)
                VALUES (OLD.id_contrato, NEW.version_actual, NEW.texto, v_id_usuario);
            END IF;
        END IF;
    END IF;

    IF v_hay_cambio THEN
        IF OLD.estado NOT IN ('BORRADOR', 'PENDIENTE_FIRMA') THEN
            RAISE EXCEPTION 'Solo se puede modificar un contrato en BORRADOR o PENDIENTE_FIRMA.';
        END IF;

        IF EXISTS (
            SELECT 1 FROM firma_contrato
            WHERE id_contrato = OLD.id_contrato
              AND estado_firma IN ('FIRMADO', 'RECHAZADO', 'INVALIDADA')
        ) THEN
            RAISE EXCEPTION 'No se puede modificar un contrato con firmas registradas.';
        END IF;

        -- La fecha se actualiza para cualquier cambio, no solo para el texto.
        NEW.fecha_modificacion := clock_timestamp();
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Valida la maquina de estados del contrato.
CREATE OR REPLACE FUNCTION fn_validar_transicion_contrato() RETURNS trigger AS $$
DECLARE
    v_id_usuario BIGINT;
    v_director_activo INT;
    v_recipientes INT;
    v_total INT;
    v_firmados INT;
    v_duplicado BIGINT;
    v_auto BOOLEAN;
BEGIN
    v_id_usuario := fn_usuario_actual();

    IF NEW.estado = OLD.estado THEN
        RETURN NEW;
    END IF;

    -- UC-54: la baja logica se permite desde cualquier estado de contrato.
    IF NEW.estado <> 'ELIMINADO' AND NOT (
        (OLD.estado = 'BORRADOR' AND NEW.estado = 'PENDIENTE_FIRMA')
        OR (OLD.estado = 'PENDIENTE_FIRMA' AND NEW.estado IN ('ACTIVO', 'RECHAZADO_POR_PARTES', 'CANCELADO'))
        OR (OLD.estado = 'ACTIVO' AND NEW.estado = 'CANCELADO')
    ) THEN
        RAISE EXCEPTION 'Transicion de contrato no permitida: % -> %.', OLD.estado, NEW.estado;
    END IF;

    -- Solo el director puede cancelar o eliminar manualmente.
    -- Las cancelaciones automaticas marcan app.contract_auto_cancel = 'on'.
    v_auto := COALESCE(current_setting('app.contract_auto_cancel', true), 'off') = 'on';

    IF NEW.estado IN ('CANCELADO', 'ELIMINADO') AND NOT v_auto AND v_id_usuario IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1
            FROM miembros_proyecto mp
            JOIN perfil p ON p.id_perfil = mp.id_perfil
            JOIN rol_proyecto rp ON rp.id_rol_proyecto = mp.id_rol_proyecto
            WHERE mp.id_proyecto = NEW.id_proyecto
              AND rp.codigo = 'DIRECTOR'
              AND mp.estado_participacion = 'ACTIVO'
              AND p.id_usuario = v_id_usuario
        ) THEN
            RAISE EXCEPTION 'Solo el director del proyecto puede cancelar o eliminar un contrato.';
        END IF;
    END IF;

    IF NEW.estado = 'PENDIENTE_FIRMA' THEN
        SELECT COUNT(*) INTO v_director_activo
        FROM miembros_proyecto mp
        JOIN rol_proyecto rp ON rp.id_rol_proyecto = mp.id_rol_proyecto
        WHERE mp.id_miembro = NEW.id_miembro_emisor
          AND mp.id_proyecto = NEW.id_proyecto
          AND rp.codigo = 'DIRECTOR'
          AND mp.estado_participacion = 'ACTIVO';

        IF v_director_activo = 0 THEN
            RAISE EXCEPTION 'El emisor del contrato debe ser un director activo del proyecto.';
        END IF;

        IF NOT EXISTS (
            SELECT 1 FROM proyecto
            WHERE id_proyecto = NEW.id_proyecto
              AND estado IN ('PUBLICADO', 'CONFIRMADO')
        ) THEN
            RAISE EXCEPTION 'Solo se puede emitir un contrato para un proyecto PUBLICADO o CONFIRMADO.';
        END IF;

        SELECT COUNT(*) INTO v_recipientes
        FROM firma_contrato
        WHERE id_contrato = NEW.id_contrato
          AND rol_parte IN ('DESTINATARIO', 'DIRECTOR_DESTINATARIO');

        IF v_recipientes = 0 THEN
            RAISE EXCEPTION 'El contrato debe tener al menos un destinatario.';
        END IF;

        IF NEW.texto IS NULL OR btrim(NEW.texto) = '' THEN
            RAISE EXCEPTION 'El contrato debe tener texto antes de emitirse.';
        END IF;

        PERFORM pg_advisory_xact_lock(
            hashtext('contrato_dup_' || NEW.id_proyecto || '_' || NEW.id_tipo_acuerdo)::bigint
        );

        v_duplicado := fn_contrato_tiene_duplicado_activo(
            NEW.id_contrato, NEW.id_proyecto, NEW.id_tipo_acuerdo
        );

        IF v_duplicado IS NOT NULL THEN
            RAISE EXCEPTION 'El miembro % ya tiene un contrato ACTIVO del mismo tipo en este proyecto.', v_duplicado;
        END IF;

        NEW.fecha_emision := COALESCE(NEW.fecha_emision, clock_timestamp());
    END IF;

    IF NEW.estado = 'ACTIVO' THEN
        SELECT COUNT(*) FILTER (WHERE estado_firma IN ('PENDIENTE', 'FIRMADO')),
               COUNT(*) FILTER (WHERE estado_firma = 'FIRMADO')
          INTO v_total, v_firmados
          FROM firma_contrato
         WHERE id_contrato = NEW.id_contrato;

        IF v_total = 0 OR v_firmados <> v_total THEN
            RAISE EXCEPTION 'El contrato no puede activarse si no todas las partes firmaron.';
        END IF;

        PERFORM pg_advisory_xact_lock(
            hashtext('contrato_dup_' || NEW.id_proyecto || '_' || NEW.id_tipo_acuerdo)::bigint
        );

        v_duplicado := fn_contrato_tiene_duplicado_activo(
            NEW.id_contrato, NEW.id_proyecto, NEW.id_tipo_acuerdo
        );

        IF v_duplicado IS NOT NULL THEN
            RAISE EXCEPTION 'El miembro % ya tiene otro contrato ACTIVO del mismo tipo en este proyecto.', v_duplicado;
        END IF;
    END IF;

    IF NEW.estado = 'CANCELADO' THEN
        IF NEW.motivo_cancelacion IS NULL OR btrim(NEW.motivo_cancelacion) = '' THEN
            RAISE EXCEPTION 'La cancelacion del contrato requiere un motivo.';
        END IF;
        NEW.fecha_cancelacion := COALESCE(NEW.fecha_cancelacion, clock_timestamp());
    END IF;

    IF NEW.estado = 'ELIMINADO' THEN
        IF EXISTS (
            SELECT 1 FROM proyecto
            WHERE id_proyecto = NEW.id_proyecto
              AND estado IN ('FINALIZADO', 'CANCELADO')
        ) THEN
            RAISE EXCEPTION 'No se puede eliminar un contrato de un proyecto finalizado o cancelado.';
        END IF;

        -- La baja logica es equivalente a una cancelacion: el motivo original
        -- queda registrado en los eventos del contrato.
        NEW.fecha_cancelacion := NULL;
        NEW.motivo_cancelacion := NULL;
        NEW.fecha_baja := COALESCE(NEW.fecha_baja, clock_timestamp());
    END IF;

    IF NEW.estado = 'RECHAZADO_POR_PARTES' THEN
        IF NOT EXISTS (
            SELECT 1 FROM firma_contrato
            WHERE id_contrato = NEW.id_contrato AND estado_firma = 'RECHAZADO'
        ) THEN
            RAISE EXCEPTION 'No se puede pasar a RECHAZADO_POR_PARTES sin una firma rechazada.';
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Efectos colaterales de la transicion de estado del contrato.
CREATE OR REPLACE FUNCTION fn_post_transicion_contrato() RETURNS trigger AS $$
DECLARE
    v_id_usuario BIGINT;
    v_id_version BIGINT;
BEGIN
    v_id_usuario := fn_usuario_actual();

    IF TG_OP = 'INSERT' THEN
        IF NEW.texto IS NOT NULL AND btrim(NEW.texto) <> '' THEN
            INSERT INTO contrato_version (id_contrato, version, texto, id_usuario)
            VALUES (NEW.id_contrato, NEW.version_actual, NEW.texto, v_id_usuario)
            ON CONFLICT (id_contrato, version) DO NOTHING;
        END IF;

        SELECT cv.id_contrato_version INTO v_id_version
        FROM contrato_version cv
        WHERE cv.id_contrato = NEW.id_contrato
          AND cv.version = NEW.version_actual;

        PERFORM fn_registrar_evento_contrato(
            NEW.id_contrato, NEW.id_miembro_emisor, v_id_usuario, 'CREADO', v_id_version, NULL
        );

        RETURN NULL;
    END IF;

    IF NEW.estado = OLD.estado THEN
        RETURN NULL;
    END IF;

    IF NEW.estado = 'PENDIENTE_FIRMA' THEN
        -- Asegurar que exista la version 1 si el borrador no tenia texto al crearse.
        IF NOT EXISTS (SELECT 1 FROM contrato_version WHERE id_contrato = NEW.id_contrato) THEN
            INSERT INTO contrato_version (id_contrato, version, texto, id_usuario)
            VALUES (NEW.id_contrato, NEW.version_actual, NEW.texto, v_id_usuario)
            ON CONFLICT (id_contrato, version) DO NOTHING;
        END IF;

        -- Asegurar que todas las firmas del borrador queden pendientes al emitir.
        UPDATE firma_contrato
           SET estado_firma = 'PENDIENTE',
               fecha_firma = NULL,
               fecha_rechazo = NULL,
               motivo_rechazo = NULL,
               id_contrato_version = NULL
         WHERE id_contrato = NEW.id_contrato
           AND estado_firma <> 'PENDIENTE';

        -- Asegurar la fila de firma del director emisor.
        INSERT INTO firma_contrato (id_miembro, id_contrato, rol_parte, estado_firma)
        VALUES (
            NEW.id_miembro_emisor,
            NEW.id_contrato,
            CASE
                WHEN EXISTS (
                    SELECT 1 FROM firma_contrato
                    WHERE id_contrato = NEW.id_contrato
                      AND id_miembro = NEW.id_miembro_emisor
                      AND rol_parte IN ('DESTINATARIO', 'DIRECTOR_DESTINATARIO')
                ) THEN 'DIRECTOR_DESTINATARIO'
                ELSE 'DIRECTOR'
            END,
            'PENDIENTE'
        )
        ON CONFLICT (id_miembro, id_contrato) DO UPDATE
        SET rol_parte = CASE
                WHEN firma_contrato.rol_parte IN ('DESTINATARIO', 'DIRECTOR_DESTINATARIO')
                THEN 'DIRECTOR_DESTINATARIO'
                ELSE 'DIRECTOR'
            END,
            estado_firma = 'PENDIENTE',
            fecha_firma = NULL,
            fecha_rechazo = NULL,
            motivo_rechazo = NULL,
            id_contrato_version = NULL;

        SELECT cv.id_contrato_version INTO v_id_version
        FROM contrato_version cv
        WHERE cv.id_contrato = NEW.id_contrato
          AND cv.version = NEW.version_actual;

        PERFORM fn_registrar_evento_contrato(
            NEW.id_contrato, NEW.id_miembro_emisor, v_id_usuario, 'EMITIDO', v_id_version, NULL
        );

        PERFORM fn_notificar_partes_contrato(
            NEW.id_contrato,
            'CONTRATO_PENDIENTE_FIRMA',
            'El contrato "' || NEW.nombre || '" esta pendiente de firma.'
        );

        RETURN NULL;
    END IF;

    IF NEW.estado = 'ACTIVO' THEN
        SELECT cv.id_contrato_version INTO v_id_version
        FROM contrato_version cv
        WHERE cv.id_contrato = NEW.id_contrato
          AND cv.version = NEW.version_actual;

        PERFORM fn_registrar_evento_contrato(
            NEW.id_contrato, NULL, v_id_usuario, 'ACTIVADO', v_id_version, NULL
        );

        PERFORM fn_notificar_partes_contrato(
            NEW.id_contrato,
            'CONTRATO_ACTIVO',
            'El contrato "' || NEW.nombre || '" fue firmado por todas las partes.'
        );

        RETURN NULL;
    END IF;

    IF NEW.estado = 'RECHAZADO_POR_PARTES' THEN
        UPDATE firma_contrato
           SET estado_firma = 'CANCELADA'
         WHERE id_contrato = NEW.id_contrato
           AND estado_firma = 'PENDIENTE';

        PERFORM fn_notificar_partes_contrato(
            NEW.id_contrato,
            'CONTRATO_RECHAZADO',
            'El contrato "' || NEW.nombre || '" fue rechazado por una de las partes.'
        );

        PERFORM fn_notificar_director_proyecto(
            NEW.id_proyecto,
            'CONTRATO_RECHAZADO',
            'El contrato "' || NEW.nombre || '" fue rechazado por una de las partes.',
            NEW.id_contrato
        );

        RETURN NULL;
    END IF;

    IF NEW.estado = 'CANCELADO' THEN
        UPDATE firma_contrato
           SET estado_firma = 'CANCELADA'
         WHERE id_contrato = NEW.id_contrato
           AND estado_firma = 'PENDIENTE';

        SELECT cv.id_contrato_version INTO v_id_version
        FROM contrato_version cv
        WHERE cv.id_contrato = NEW.id_contrato
          AND cv.version = NEW.version_actual;

        PERFORM fn_registrar_evento_contrato(
            NEW.id_contrato, NULL, v_id_usuario, 'CANCELADO', v_id_version, NEW.motivo_cancelacion
        );

        PERFORM fn_notificar_partes_contrato(
            NEW.id_contrato,
            'CONTRATO_CANCELADO',
            'El contrato "' || NEW.nombre || '" fue cancelado. Motivo: ' || COALESCE(NEW.motivo_cancelacion, 'No especificado') || '.'
        );

        PERFORM fn_notificar_director_proyecto(
            NEW.id_proyecto,
            'CONTRATO_CANCELADO',
            'El contrato "' || NEW.nombre || '" fue cancelado. Motivo: ' || COALESCE(NEW.motivo_cancelacion, 'No especificado') || '.',
            NEW.id_contrato
        );

        RETURN NULL;
    END IF;

    IF NEW.estado = 'ELIMINADO' THEN
        UPDATE firma_contrato
           SET estado_firma = 'CANCELADA'
         WHERE id_contrato = NEW.id_contrato
           AND estado_firma = 'PENDIENTE';

        SELECT cv.id_contrato_version INTO v_id_version
        FROM contrato_version cv
        WHERE cv.id_contrato = NEW.id_contrato
          AND cv.version = NEW.version_actual;

        PERFORM fn_registrar_evento_contrato(
            NEW.id_contrato, NULL, v_id_usuario, 'ELIMINADO', v_id_version, NULL
        );

        IF OLD.estado <> 'BORRADOR' THEN
            PERFORM fn_notificar_partes_contrato(
                NEW.id_contrato,
                'CONTRATO_ELIMINADO',
                'El contrato "' || NEW.nombre || '" fue eliminado.'
            );
        END IF;

        RETURN NULL;
    END IF;

    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- Notifica una modificacion de contrato a las partes actuales.
-- No deduplica entre modificaciones: cada modificacion genera su aviso.
CREATE OR REPLACE FUNCTION fn_notificar_partes_contrato_modificado(
    p_id_contrato BIGINT,
    p_tipo VARCHAR,
    p_mensaje TEXT
) RETURNS void AS $$
DECLARE
    r_dest RECORD;
    v_id_proyecto BIGINT;
BEGIN
    SELECT c.id_proyecto INTO v_id_proyecto
    FROM contrato c
    WHERE c.id_contrato = p_id_contrato;

    FOR r_dest IN
        SELECT DISTINCT p.id_usuario, p.id_perfil
        FROM firma_contrato f
        JOIN miembros_proyecto mp ON mp.id_miembro = f.id_miembro
        JOIN perfil p ON p.id_perfil = mp.id_perfil
        WHERE f.id_contrato = p_id_contrato
          AND mp.estado_participacion = 'ACTIVO'
    LOOP
        INSERT INTO notificacion (
            id_usuario_destino,
            id_perfil_contexto,
            tipo,
            mensaje,
            entidad_tipo,
            entidad_id,
            id_proyecto,
            leida,
            fecha_leida,
            origen,
            fecha_generada
        ) VALUES (
            r_dest.id_usuario,
            r_dest.id_perfil,
            p_tipo,
            p_mensaje,
            'CONTRATO',
            p_id_contrato,
            v_id_proyecto,
            false,
            NULL,
            'TRIGGER',
            clock_timestamp()
        );
    END LOOP;
END;
$$ LANGUAGE plpgsql;

-- Registra el evento MODIFICADO y notifica a las partes actuales cuando se
-- actualizan datos editables del contrato sin cambiar su estado.
CREATE OR REPLACE FUNCTION fn_post_modificacion_contrato() RETURNS trigger AS $$
DECLARE
    v_id_version BIGINT;
BEGIN
    IF OLD.estado <> 'PENDIENTE_FIRMA' OR NEW.estado <> 'PENDIENTE_FIRMA' THEN
        RETURN NULL;
    END IF;

    IF NEW.id_tipo_acuerdo = OLD.id_tipo_acuerdo
       AND NEW.nombre = OLD.nombre
       AND NEW.descripcion IS NOT DISTINCT FROM OLD.descripcion
       AND NEW.texto IS NOT DISTINCT FROM OLD.texto
       AND NEW.fecha_modificacion IS NOT DISTINCT FROM OLD.fecha_modificacion THEN
        RETURN NULL;
    END IF;

    SELECT cv.id_contrato_version INTO v_id_version
    FROM contrato_version cv
    WHERE cv.id_contrato = NEW.id_contrato
      AND cv.version = NEW.version_actual;

    PERFORM fn_registrar_evento_contrato(
        NEW.id_contrato,
        NEW.id_miembro_emisor,
        fn_usuario_actual(),
        'MODIFICADO',
        v_id_version,
        'Modificacion de datos del contrato'
    );

    PERFORM fn_notificar_partes_contrato_modificado(
        NEW.id_contrato,
        'CONTRATO_MODIFICADO',
        'El contrato "' || NEW.nombre || '" fue modificado y esta pendiente de firma.'
    );

    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- ============================================================================
-- VALIDACION Y AUDITORIA DE FIRMAS
-- ============================================================================

CREATE OR REPLACE FUNCTION fn_validar_firma_contrato() RETURNS trigger AS $$
DECLARE
    v_estado_contrato      VARCHAR(50);
    v_id_proyecto_contrato BIGINT;
    v_version_actual       INT;
    v_id_proyecto_miembro  BIGINT;
    v_estado_participacion VARCHAR(50);
BEGIN
    -- Las actualizaciones internas de cascada no se revalidan.
    IF pg_trigger_depth() > 1 THEN
        RETURN NEW;
    END IF;

    SELECT c.estado, c.id_proyecto, c.version_actual
      INTO v_estado_contrato, v_id_proyecto_contrato, v_version_actual
      FROM contrato c
     WHERE c.id_contrato = NEW.id_contrato;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'El contrato % no existe.', NEW.id_contrato
            USING ERRCODE = 'foreign_key_violation';
    END IF;

    SELECT m.id_proyecto, m.estado_participacion
      INTO v_id_proyecto_miembro, v_estado_participacion
      FROM miembros_proyecto m
     WHERE m.id_miembro = NEW.id_miembro;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'El miembro de proyecto % no existe.', NEW.id_miembro
            USING ERRCODE = 'foreign_key_violation';
    END IF;

    IF v_id_proyecto_miembro <> v_id_proyecto_contrato THEN
        RAISE EXCEPTION 'El miembro % no pertenece al proyecto del contrato %.',
            NEW.id_miembro, NEW.id_contrato
            USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.rol_parte IN ('DIRECTOR', 'DIRECTOR_DESTINATARIO') THEN
        IF NOT EXISTS (
            SELECT 1 FROM contrato c
            WHERE c.id_contrato = NEW.id_contrato
              AND c.id_miembro_emisor = NEW.id_miembro
        ) THEN
            RAISE EXCEPTION 'La fila de director debe corresponder al director emisor del contrato.';
        END IF;
    END IF;

    IF TG_OP = 'INSERT' AND v_estado_contrato NOT IN ('BORRADOR', 'PENDIENTE_FIRMA') THEN
        RAISE EXCEPTION 'Solo se pueden agregar partes a un contrato en BORRADOR o PENDIENTE_FIRMA.';
    END IF;

    IF TG_OP = 'INSERT' AND NEW.estado_firma <> 'PENDIENTE' THEN
        RAISE EXCEPTION 'Una nueva firma debe crearse en estado PENDIENTE.';
    END IF;

    IF TG_OP = 'INSERT' AND v_estado_participacion <> 'ACTIVO' THEN
        RAISE EXCEPTION 'Solo un miembro ACTIVO puede ser parte de un contrato.';
    END IF;

    IF NEW.estado_firma IN ('FIRMADO', 'RECHAZADO') THEN
        IF v_estado_contrato <> 'PENDIENTE_FIRMA' THEN
            RAISE EXCEPTION 'Solo se puede firmar o rechazar un contrato en PENDIENTE_FIRMA (contrato % en estado %).',
                NEW.id_contrato, v_estado_contrato
                USING ERRCODE = 'check_violation';
        END IF;

        IF v_estado_participacion <> 'ACTIVO' THEN
            RAISE EXCEPTION 'Solo un miembro ACTIVO puede firmar o rechazar el contrato %.', NEW.id_contrato
                USING ERRCODE = 'check_violation';
        END IF;

        IF NEW.estado_firma = 'RECHAZADO' AND (NEW.motivo_rechazo IS NULL OR btrim(NEW.motivo_rechazo) = '') THEN
            RAISE EXCEPTION 'El rechazo de la firma requiere un motivo.';
        END IF;

        IF NEW.id_contrato_version IS NULL THEN
            SELECT cv.id_contrato_version
              INTO NEW.id_contrato_version
              FROM contrato c
              JOIN contrato_version cv
                ON cv.id_contrato = c.id_contrato
               AND cv.version = c.version_actual
             WHERE c.id_contrato = NEW.id_contrato;
        END IF;

        IF NEW.id_contrato_version IS NULL THEN
            RAISE EXCEPTION 'No existe la version actual del contrato %.', NEW.id_contrato;
        END IF;

        IF NOT EXISTS (
            SELECT 1
            FROM contrato c
            JOIN contrato_version cv
              ON cv.id_contrato = c.id_contrato
             AND cv.version = c.version_actual
            WHERE c.id_contrato = NEW.id_contrato
              AND cv.id_contrato_version = NEW.id_contrato_version
        ) THEN
            RAISE EXCEPTION 'La version firmada no es la version actual del contrato.';
        END IF;

        IF NEW.estado_firma = 'FIRMADO' AND NEW.fecha_firma IS NULL THEN
            NEW.fecha_firma := clock_timestamp();
        END IF;

        IF NEW.estado_firma = 'RECHAZADO' AND NEW.fecha_rechazo IS NULL THEN
            NEW.fecha_rechazo := clock_timestamp();
        END IF;
    END IF;

    IF TG_OP = 'UPDATE' AND OLD.estado_firma IN ('FIRMADO', 'RECHAZADO', 'INVALIDADA')
       AND NEW.estado_firma <> OLD.estado_firma THEN
        RAISE EXCEPTION 'No se puede cambiar el estado de una firma ya registrada.';
    END IF;

    IF TG_OP = 'UPDATE' AND OLD.estado_firma <> 'PENDIENTE'
       AND NEW.rol_parte <> OLD.rol_parte THEN
        RAISE EXCEPTION 'No se puede cambiar el rol de una firma ya registrada.';
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION fn_auditar_firma_contrato() RETURNS trigger AS $$
DECLARE
    v_id_usuario BIGINT;
BEGIN
    IF pg_trigger_depth() > 1 THEN
        RETURN NULL;
    END IF;

    v_id_usuario := fn_usuario_actual();

    IF TG_OP = 'INSERT' THEN
        RETURN NULL;
    END IF;

    IF OLD.estado_firma = NEW.estado_firma THEN
        RETURN NULL;
    END IF;

    IF NEW.estado_firma = 'FIRMADO' THEN
        PERFORM fn_registrar_evento_contrato(
            NEW.id_contrato, NEW.id_miembro, v_id_usuario, 'FIRMADO', NEW.id_contrato_version, NULL
        );
    ELSIF NEW.estado_firma = 'RECHAZADO' THEN
        PERFORM fn_registrar_evento_contrato(
            NEW.id_contrato, NEW.id_miembro, v_id_usuario, 'RECHAZADO', NEW.id_contrato_version, NEW.motivo_rechazo
        );
    ELSIF NEW.estado_firma = 'CANCELADA' THEN
        PERFORM fn_registrar_evento_contrato(
            NEW.id_contrato, NEW.id_miembro, v_id_usuario, 'FIRMA_CANCELADA', NULL, NULL
        );
    ELSIF NEW.estado_firma = 'INVALIDADA' THEN
        PERFORM fn_registrar_evento_contrato(
            NEW.id_contrato, NEW.id_miembro, v_id_usuario, 'FIRMA_INVALIDADA', NEW.id_contrato_version, NULL
        );
    END IF;

    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION fn_impedir_borrado_firma() RETURNS trigger AS $$
BEGIN
    IF OLD.estado_firma IN ('FIRMADO', 'RECHAZADO', 'INVALIDADA') THEN
        RAISE EXCEPTION 'No se puede eliminar una firma registrada del contrato %.', OLD.id_contrato;
    END IF;
    RETURN OLD;
END;
$$ LANGUAGE plpgsql;

-- Actualiza el estado del contrato cuando cambia una firma.
CREATE OR REPLACE FUNCTION fn_actualizar_estado_contrato() RETURNS trigger AS $$
DECLARE
    v_estado_contrato VARCHAR(50);
    v_total INT;
    v_firmados INT;
    v_rechazados INT;
    v_invalidados INT;
BEGIN
    -- Las actualizaciones internas de cascada no disparan otra transicion.
    IF pg_trigger_depth() > 1 THEN
        RETURN NULL;
    END IF;

    SELECT estado INTO v_estado_contrato
      FROM contrato
     WHERE id_contrato = NEW.id_contrato;

    IF v_estado_contrato NOT IN ('PENDIENTE_FIRMA', 'ACTIVO') THEN
        RETURN NULL;
    END IF;

    SELECT COUNT(*) FILTER (WHERE estado_firma IN ('PENDIENTE', 'FIRMADO')),
           COUNT(*) FILTER (WHERE estado_firma = 'FIRMADO'),
           COUNT(*) FILTER (WHERE estado_firma = 'RECHAZADO'),
           COUNT(*) FILTER (WHERE estado_firma = 'INVALIDADA')
      INTO v_total, v_firmados, v_rechazados, v_invalidados
      FROM firma_contrato
     WHERE id_contrato = NEW.id_contrato;

    IF v_rechazados > 0 THEN
        UPDATE contrato
           SET estado = 'RECHAZADO_POR_PARTES'
         WHERE id_contrato = NEW.id_contrato
           AND estado = 'PENDIENTE_FIRMA';
        RETURN NULL;
    END IF;

    IF v_invalidados > 0 THEN
        PERFORM set_config('app.contract_auto_cancel', 'on', true);

        UPDATE contrato
           SET estado = 'CANCELADO',
               motivo_cancelacion = COALESCE(motivo_cancelacion, 'BAJA_FIRMANTE'),
               fecha_cancelacion = COALESCE(fecha_cancelacion, clock_timestamp())
         WHERE id_contrato = NEW.id_contrato
           AND estado IN ('PENDIENTE_FIRMA', 'ACTIVO');

        PERFORM set_config('app.contract_auto_cancel', 'off', true);
        RETURN NULL;
    END IF;

    IF v_total > 0 AND v_firmados = v_total AND v_estado_contrato = 'PENDIENTE_FIRMA' THEN
        UPDATE contrato
           SET estado = 'ACTIVO'
         WHERE id_contrato = NEW.id_contrato;
    END IF;

    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- ============================================================================
-- BAJA DE FIRMANTES
-- ============================================================================

CREATE OR REPLACE FUNCTION fn_cancelar_contratos_por_baja_miembro() RETURNS trigger AS $$
DECLARE
    r_firma RECORD;
    v_es_director BOOLEAN;
    v_hay_firmado BOOLEAN;
    v_id_usuario BIGINT;
    v_cambio_rol BOOLEAN;
BEGIN
    v_cambio_rol := (
        OLD.id_rol_proyecto <> NEW.id_rol_proyecto
        AND OLD.id_rol_proyecto = (SELECT id_rol_proyecto FROM rol_proyecto WHERE codigo = 'DIRECTOR')
        AND NEW.estado_participacion = 'ACTIVO'
    );

    IF NOT (
        (OLD.estado_participacion = 'ACTIVO' AND NEW.estado_participacion <> 'ACTIVO')
        OR v_cambio_rol
    ) THEN
        RETURN NEW;
    END IF;

    v_id_usuario := fn_usuario_actual();

    PERFORM set_config('app.contract_auto_cancel', 'on', true);

    FOR r_firma IN
        SELECT f.id_contrato,
               f.rol_parte,
               f.estado_firma,
               c.id_miembro_emisor,
               c.id_proyecto,
               c.estado AS estado_contrato
          FROM firma_contrato f
          JOIN contrato c ON c.id_contrato = f.id_contrato
         WHERE f.id_miembro = OLD.id_miembro
           AND f.estado_firma IN ('PENDIENTE', 'FIRMADO')
           AND c.estado IN ('PENDIENTE_FIRMA', 'ACTIVO')
    LOOP
        v_es_director := (r_firma.id_miembro_emisor = OLD.id_miembro)
                         OR r_firma.rol_parte IN ('DIRECTOR', 'DIRECTOR_DESTINATARIO');

        IF r_firma.estado_firma = 'PENDIENTE' THEN
            UPDATE firma_contrato
               SET estado_firma = 'CANCELADA'
             WHERE id_contrato = r_firma.id_contrato
               AND id_miembro = OLD.id_miembro;

            PERFORM fn_registrar_evento_contrato(
                r_firma.id_contrato, OLD.id_miembro, v_id_usuario,
                'FIRMA_CANCELADA', NULL, 'MIEMBRO_BAJA'
            );
        ELSIF r_firma.estado_firma = 'FIRMADO' THEN
            UPDATE firma_contrato
               SET estado_firma = 'INVALIDADA'
             WHERE id_contrato = r_firma.id_contrato
               AND id_miembro = OLD.id_miembro;

            PERFORM fn_registrar_evento_contrato(
                r_firma.id_contrato, OLD.id_miembro, v_id_usuario,
                'FIRMA_INVALIDADA', NULL, 'MIEMBRO_BAJA'
            );
        END IF;

        IF v_es_director THEN
            UPDATE contrato
               SET estado = 'CANCELADO',
                   motivo_cancelacion = 'BAJA_DIRECTOR',
                   fecha_cancelacion = COALESCE(fecha_cancelacion, clock_timestamp())
             WHERE id_contrato = r_firma.id_contrato
               AND estado IN ('PENDIENTE_FIRMA', 'ACTIVO');

        ELSIF r_firma.estado_firma = 'FIRMADO' THEN
            UPDATE contrato
               SET estado = 'CANCELADO',
                   motivo_cancelacion = 'BAJA_FIRMANTE',
                   fecha_cancelacion = COALESCE(fecha_cancelacion, clock_timestamp())
             WHERE id_contrato = r_firma.id_contrato
               AND estado IN ('PENDIENTE_FIRMA', 'ACTIVO');

        ELSE
            SELECT EXISTS (
                SELECT 1 FROM firma_contrato
                WHERE id_contrato = r_firma.id_contrato
                  AND estado_firma = 'FIRMADO'
            ) INTO v_hay_firmado;

            IF v_hay_firmado THEN
                UPDATE contrato
                   SET estado = 'CANCELADO',
                       motivo_cancelacion = 'BAJA_FIRMANTE',
                       fecha_cancelacion = COALESCE(fecha_cancelacion, clock_timestamp())
                 WHERE id_contrato = r_firma.id_contrato
                   AND estado IN ('PENDIENTE_FIRMA', 'ACTIVO');
            END IF;
        END IF;

        PERFORM fn_registrar_evento_contrato(
            r_firma.id_contrato, OLD.id_miembro, v_id_usuario,
            'MIEMBRO_BAJA', NULL, NEW.estado_participacion
        );
    END LOOP;

    PERFORM set_config('app.contract_auto_cancel', 'off', true);

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
-- ============================================================================
-- TRIGGERS DEL MODULO DE CONTRATOS
-- ============================================================================

CREATE OR REPLACE FUNCTION fn_impedir_borrado_contrato() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'La eliminacion fisica de contratos no esta permitida; use la baja logica.';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_contrato_insert ON contrato;
CREATE TRIGGER trg_contrato_insert
    BEFORE INSERT ON contrato
    FOR EACH ROW EXECUTE FUNCTION fn_validar_contrato_insert();

DROP TRIGGER IF EXISTS trg_contrato_editable ON contrato;
CREATE TRIGGER trg_contrato_editable
    BEFORE UPDATE ON contrato
    FOR EACH ROW EXECUTE FUNCTION fn_validar_contrato_editable();

DROP TRIGGER IF EXISTS trg_contrato_transicion ON contrato;
CREATE TRIGGER trg_contrato_transicion
    BEFORE UPDATE OF estado ON contrato
    FOR EACH ROW EXECUTE FUNCTION fn_validar_transicion_contrato();

DROP TRIGGER IF EXISTS trg_contrato_post_transicion ON contrato;
CREATE TRIGGER trg_contrato_post_transicion
    AFTER INSERT OR UPDATE OF estado ON contrato
    FOR EACH ROW EXECUTE FUNCTION fn_post_transicion_contrato();

DROP TRIGGER IF EXISTS trg_contrato_modificacion ON contrato;
CREATE TRIGGER trg_contrato_modificacion
    AFTER UPDATE OF id_tipo_acuerdo, nombre, descripcion, texto, fecha_modificacion
    ON contrato
    FOR EACH ROW EXECUTE FUNCTION fn_post_modificacion_contrato();

DROP TRIGGER IF EXISTS trg_contrato_impedir_delete ON contrato;
CREATE TRIGGER trg_contrato_impedir_delete
    BEFORE DELETE ON contrato
    FOR EACH ROW EXECUTE FUNCTION fn_impedir_borrado_contrato();

DROP TRIGGER IF EXISTS trg_aa_auditar_firma_contrato ON firma_contrato;
CREATE TRIGGER trg_aa_auditar_firma_contrato
    AFTER INSERT OR UPDATE ON firma_contrato
    FOR EACH ROW EXECUTE FUNCTION fn_auditar_firma_contrato();

DROP TRIGGER IF EXISTS trg_ab_validar_firma_contrato ON firma_contrato;
CREATE TRIGGER trg_ab_validar_firma_contrato
    BEFORE INSERT OR UPDATE ON firma_contrato
    FOR EACH ROW EXECUTE FUNCTION fn_validar_firma_contrato();

DROP TRIGGER IF EXISTS trg_ac_impedir_borrado_firma ON firma_contrato;
CREATE TRIGGER trg_ac_impedir_borrado_firma
    BEFORE DELETE ON firma_contrato
    FOR EACH ROW EXECUTE FUNCTION fn_impedir_borrado_firma();

DROP TRIGGER IF EXISTS trg_zz_actualizar_estado_contrato ON firma_contrato;
CREATE TRIGGER trg_zz_actualizar_estado_contrato
    AFTER INSERT OR UPDATE ON firma_contrato
    FOR EACH ROW EXECUTE FUNCTION fn_actualizar_estado_contrato();

DROP TRIGGER IF EXISTS trg_cancelar_contratos_por_baja_miembro ON miembros_proyecto;
CREATE TRIGGER trg_cancelar_contratos_por_baja_miembro
    AFTER UPDATE OF id_rol_proyecto, estado_participacion ON miembros_proyecto
    FOR EACH ROW EXECUTE FUNCTION fn_cancelar_contratos_por_baja_miembro();

