-- ============================================================================
-- UC-76 - Gestion de tipos de contrato (ABM admin)
-- ============================================================================
-- 1) PERMISOS
-- ============================================================================

INSERT INTO permiso_global (nombre)
SELECT v.nombre
FROM (VALUES
    ('VER_TIPOS_CONTRATO'),
    ('CREAR_TIPO_CONTRATO'),
    ('MODIFICAR_TIPO_CONTRATO'),
    ('ELIMINAR_TIPO_CONTRATO')
) AS v(nombre)
WHERE NOT EXISTS (
    SELECT 1 FROM permiso_global pg WHERE pg.nombre = v.nombre
);

INSERT INTO rol_global_permiso (id_rol_global, id_permiso_global)
SELECT rg.id_rol_global, pg.id_permiso_global
FROM rol_global rg
CROSS JOIN permiso_global pg
WHERE rg.nombre = 'Administrador'
  AND pg.nombre IN (
      'VER_TIPOS_CONTRATO',
      'CREAR_TIPO_CONTRATO',
      'MODIFICAR_TIPO_CONTRATO',
      'ELIMINAR_TIPO_CONTRATO'
  )
ON CONFLICT DO NOTHING;

-- ============================================================================
-- 2) INDICES
-- ============================================================================

-- El codigo se genera automaticamente y no se repite. El indice funcional
-- evita duplicados que solo difieran en mayusculas/minusculas.
CREATE UNIQUE INDEX IF NOT EXISTS uq_tipo_acuerdo_contrato_codigo_lower
    ON tipo_acuerdo_contrato (lower(codigo));

-- La unicidad de nombre se valida en el servicio. No se impone un indice
-- parcial porque las pruebas y los datos historicos pueden reutilizar nombres
-- en tipos inactivos.

-- ============================================================================
-- 3) AUDITORIA
-- ============================================================================

INSERT INTO tipo_evento_auditoria (codigo, nombre, descripcion, modulo) VALUES
    ('TIPO_CONTRATO_CREADO', 'Alta de tipo de contrato',
        'Alta de un tipo de acuerdo para contratos', 'ADMINISTRACION'),
    ('TIPO_CONTRATO_MODIFICADO', 'Modificacion de tipo de contrato',
        'Cambio de nombre, descripcion o plantilla de un tipo de contrato', 'ADMINISTRACION'),
    ('TIPO_CONTRATO_ESTADO_CAMBIADO', 'Cambio de estado de tipo de contrato',
        'Activacion o desactivacion de un tipo de contrato', 'ADMINISTRACION'),
    ('TIPO_CONTRATO_ELIMINADO', 'Baja de tipo de contrato',
        'Eliminacion fisica de un tipo de contrato sin contratos asociados', 'ADMINISTRACION')
ON CONFLICT (codigo) DO UPDATE
    SET nombre = EXCLUDED.nombre,
        descripcion = EXCLUDED.descripcion,
        modulo = EXCLUDED.modulo,
        activo = true;

-- La plantilla legal puede ser extensa. Para no duplicarla en el log se
-- guarda su longitud y md5.
CREATE OR REPLACE FUNCTION fn_resumen_plantilla_contrato(p_plantilla text)
RETURNS text AS $$
BEGIN
    IF p_plantilla IS NULL THEN
        RETURN NULL;
    END IF;
    RETURN '[omitido: ' || char_length(p_plantilla)
        || ' caracteres, md5=' || md5(p_plantilla) || ']';
END $$ LANGUAGE plpgsql IMMUTABLE;

CREATE OR REPLACE FUNCTION fn_auditar_tipo_acuerdo_contrato() RETURNS trigger AS $$
DECLARE
    v_id_tipo_auditoria BIGINT;
    v_id_auditoria BIGINT;
    v_id_tipo BIGINT;
    v_codigo VARCHAR(50);
    v_evento VARCHAR(40);
BEGIN
    IF TG_OP = 'UPDATE'
            AND NEW.codigo IS NOT DISTINCT FROM OLD.codigo
            AND NEW.nombre IS NOT DISTINCT FROM OLD.nombre
            AND NEW.descripcion IS NOT DISTINCT FROM OLD.descripcion
            AND NEW.plantilla IS NOT DISTINCT FROM OLD.plantilla
            AND NEW.activo IS NOT DISTINCT FROM OLD.activo THEN
        RETURN NEW;
    END IF;

    SELECT id_tipo_auditoria INTO v_id_tipo_auditoria
    FROM tipo_accion_auditoria
    WHERE nombre = TG_OP;

    IF v_id_tipo_auditoria IS NULL THEN
        RAISE EXCEPTION 'No se encontro el tipo de accion de auditoria para la operacion %', TG_OP;
    END IF;

    IF TG_OP = 'DELETE' THEN
        v_id_tipo := OLD.id_tipo_acuerdo;
        v_codigo := OLD.codigo;
        v_evento := 'TIPO_CONTRATO_ELIMINADO';
    ELSE
        v_id_tipo := NEW.id_tipo_acuerdo;
        v_codigo := NEW.codigo;
        IF TG_OP = 'INSERT' THEN
            v_evento := 'TIPO_CONTRATO_CREADO';
        ELSIF NEW.activo IS DISTINCT FROM OLD.activo
                AND NEW.codigo IS NOT DISTINCT FROM OLD.codigo
                AND NEW.nombre IS NOT DISTINCT FROM OLD.nombre
                AND NEW.descripcion IS NOT DISTINCT FROM OLD.descripcion
                AND NEW.plantilla IS NOT DISTINCT FROM OLD.plantilla THEN
            v_evento := 'TIPO_CONTRATO_ESTADO_CAMBIADO';
        ELSE
            v_evento := 'TIPO_CONTRATO_MODIFICADO';
        END IF;
    END IF;

    INSERT INTO auditoria (
        usuario_bd,
        entidad_afectada,
        entidad_clave,
        id_afectado,
        fecha_hora,
        ip_usuario,
        id_tipo_auditoria,
        id_usuario,
        tipo_evento,
        tipo_evento_original
    ) VALUES (
        CURRENT_USER,
        'tipo_acuerdo_contrato',
        v_codigo,
        v_id_tipo,
        clock_timestamp(),
        inet_client_addr()::varchar,
        v_id_tipo_auditoria,
        fn_auditoria_usuario_actual(),
        fn_evento_auditoria(v_evento),
        v_evento
    ) RETURNING id_auditoria INTO v_id_auditoria;

    IF TG_OP = 'INSERT' THEN
        INSERT INTO detalle_auditoria (campo, valor_anterior, valor_nuevo, id_auditoria)
        VALUES ('nombre', NULL, NEW.nombre, v_id_auditoria);

        IF NEW.descripcion IS NOT NULL THEN
            INSERT INTO detalle_auditoria (campo, valor_anterior, valor_nuevo, id_auditoria)
            VALUES ('descripcion', NULL, NEW.descripcion, v_id_auditoria);
        END IF;

        INSERT INTO detalle_auditoria (campo, valor_anterior, valor_nuevo, id_auditoria)
        VALUES ('plantilla', NULL,
            fn_resumen_plantilla_contrato(NEW.plantilla), v_id_auditoria);

        INSERT INTO detalle_auditoria (campo, valor_anterior, valor_nuevo, id_auditoria)
        VALUES ('activo', NULL, NEW.activo::text, v_id_auditoria);

    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO detalle_auditoria (campo, valor_anterior, valor_nuevo, id_auditoria)
        VALUES ('nombre', OLD.nombre, NULL, v_id_auditoria);

        IF OLD.descripcion IS NOT NULL THEN
            INSERT INTO detalle_auditoria (campo, valor_anterior, valor_nuevo, id_auditoria)
            VALUES ('descripcion', OLD.descripcion, NULL, v_id_auditoria);
        END IF;

        INSERT INTO detalle_auditoria (campo, valor_anterior, valor_nuevo, id_auditoria)
        VALUES ('plantilla',
            fn_resumen_plantilla_contrato(OLD.plantilla), NULL, v_id_auditoria);

        INSERT INTO detalle_auditoria (campo, valor_anterior, valor_nuevo, id_auditoria)
        VALUES ('activo', OLD.activo::text, NULL, v_id_auditoria);

    ELSE
        IF NEW.codigo IS DISTINCT FROM OLD.codigo THEN
            INSERT INTO detalle_auditoria (campo, valor_anterior, valor_nuevo, id_auditoria)
            VALUES ('codigo', OLD.codigo, NEW.codigo, v_id_auditoria);
        END IF;

        IF NEW.nombre IS DISTINCT FROM OLD.nombre THEN
            INSERT INTO detalle_auditoria (campo, valor_anterior, valor_nuevo, id_auditoria)
            VALUES ('nombre', OLD.nombre, NEW.nombre, v_id_auditoria);
        END IF;

        IF NEW.descripcion IS DISTINCT FROM OLD.descripcion THEN
            INSERT INTO detalle_auditoria (campo, valor_anterior, valor_nuevo, id_auditoria)
            VALUES ('descripcion', OLD.descripcion, NEW.descripcion, v_id_auditoria);
        END IF;

        IF NEW.plantilla IS DISTINCT FROM OLD.plantilla THEN
            INSERT INTO detalle_auditoria (campo, valor_anterior, valor_nuevo, id_auditoria)
            VALUES ('plantilla',
                fn_resumen_plantilla_contrato(OLD.plantilla),
                fn_resumen_plantilla_contrato(NEW.plantilla),
                v_id_auditoria);
        END IF;

        IF NEW.activo IS DISTINCT FROM OLD.activo THEN
            INSERT INTO detalle_auditoria (campo, valor_anterior, valor_nuevo, id_auditoria)
            VALUES ('activo', OLD.activo::text, NEW.activo::text, v_id_auditoria);
        END IF;
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_auditar_tipo_acuerdo_contrato
    ON tipo_acuerdo_contrato;

CREATE TRIGGER trg_auditar_tipo_acuerdo_contrato
    AFTER INSERT OR UPDATE OR DELETE ON tipo_acuerdo_contrato
    FOR EACH ROW EXECUTE FUNCTION fn_auditar_tipo_acuerdo_contrato();

-- ============================================================================
-- UC-43 - Enviar solicitud de conexion
-- Esquema base para UC-43, UC-44, UC-45 y UC-46.
-- ============================================================================

CREATE TABLE IF NOT EXISTS solicitud_conexion (
    id_solicitud_conexion  int8 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_perfil_remitente    int8 NOT NULL,
    id_perfil_destinatario int8 NOT NULL,
    estado                 varchar(20) DEFAULT 'PENDIENTE' NOT NULL,
    fecha_envio            timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
    fecha_respuesta        timestamp,
    CONSTRAINT "PK_solicitud_conexion" PRIMARY KEY (id_solicitud_conexion),
    CONSTRAINT fk_solicitud_conexion_remitente
        FOREIGN KEY (id_perfil_remitente) REFERENCES perfil(id_perfil),
    CONSTRAINT fk_solicitud_conexion_destinatario
        FOREIGN KEY (id_perfil_destinatario) REFERENCES perfil(id_perfil),
    CONSTRAINT chk_solicitud_conexion_no_auto
        CHECK (id_perfil_remitente <> id_perfil_destinatario),
    CONSTRAINT chk_solicitud_conexion_estado
        CHECK (estado IN ('PENDIENTE', 'ACEPTADA', 'RECHAZADA')),
    CONSTRAINT chk_solicitud_conexion_fechas
        CHECK (
            (estado = 'PENDIENTE' AND fecha_respuesta IS NULL)
            OR (estado IN ('ACEPTADA', 'RECHAZADA') AND fecha_respuesta IS NOT NULL)
        )
);

CREATE UNIQUE INDEX IF NOT EXISTS "UQ_solicitud_conexion_pendiente"
    ON solicitud_conexion (
        (LEAST(id_perfil_remitente, id_perfil_destinatario)),
        (GREATEST(id_perfil_remitente, id_perfil_destinatario))
    )
    WHERE estado = 'PENDIENTE';

CREATE INDEX IF NOT EXISTS "IDX_solicitud_conexion_destinatario"
    ON solicitud_conexion (id_perfil_destinatario, fecha_envio DESC);

CREATE INDEX IF NOT EXISTS "IDX_solicitud_conexion_remitente"
    ON solicitud_conexion (id_perfil_remitente, fecha_envio DESC);

CREATE TABLE IF NOT EXISTS conexion (
    id_conexion            int8 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_perfil_1            int8 NOT NULL,
    id_perfil_2            int8 NOT NULL,
    id_solicitud_conexion  int8 NOT NULL,
    estado                 varchar(20) DEFAULT 'ACTIVA' NOT NULL,
    fecha_inicio_conexion  timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
    fecha_fin_conexion     timestamp,
    CONSTRAINT "PK_conexion" PRIMARY KEY (id_conexion),
    CONSTRAINT fk_conexion_perfil_1
        FOREIGN KEY (id_perfil_1) REFERENCES perfil(id_perfil),
    CONSTRAINT fk_conexion_perfil_2
        FOREIGN KEY (id_perfil_2) REFERENCES perfil(id_perfil),
    CONSTRAINT fk_conexion_solicitud
        FOREIGN KEY (id_solicitud_conexion) REFERENCES solicitud_conexion(id_solicitud_conexion),
    CONSTRAINT "UQ_conexion_solicitud" UNIQUE (id_solicitud_conexion),
    CONSTRAINT chk_conexion_orden CHECK (id_perfil_1 < id_perfil_2),
    CONSTRAINT chk_conexion_estado CHECK (estado IN ('ACTIVA', 'ELIMINADA')),
    CONSTRAINT chk_conexion_fechas CHECK (
        (estado = 'ACTIVA' AND fecha_fin_conexion IS NULL)
        OR (estado = 'ELIMINADA' AND fecha_fin_conexion IS NOT NULL)
    )
);

CREATE UNIQUE INDEX IF NOT EXISTS "UQ_conexion_activa"
    ON conexion (id_perfil_1, id_perfil_2)
    WHERE estado = 'ACTIVA';

CREATE INDEX IF NOT EXISTS "IDX_conexion_perfil_2_activa"
    ON conexion (id_perfil_2)
    WHERE estado = 'ACTIVA';

CREATE OR REPLACE FUNCTION fn_validar_solicitud_conexion() RETURNS trigger AS $$
DECLARE
    v_remitente_usuario BIGINT;
    v_destinatario_usuario BIGINT;
    v_remitente_usuario_estado VARCHAR(20);
    v_destinatario_usuario_estado VARCHAR(20);
    v_remitente_perfil_estado VARCHAR(50);
    v_destinatario_perfil_estado VARCHAR(50);
BEGIN
    SELECT p.id_usuario, p.estado, u.estado
      INTO v_remitente_usuario, v_remitente_perfil_estado, v_remitente_usuario_estado
      FROM perfil p
      JOIN usuario u ON u.id_usuario = p.id_usuario
     WHERE p.id_perfil = NEW.id_perfil_remitente;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'El perfil remitente % no existe.', NEW.id_perfil_remitente
            USING ERRCODE = 'foreign_key_violation';
    END IF;

    SELECT p.id_usuario, p.estado, u.estado
      INTO v_destinatario_usuario, v_destinatario_perfil_estado, v_destinatario_usuario_estado
      FROM perfil p
      JOIN usuario u ON u.id_usuario = p.id_usuario
     WHERE p.id_perfil = NEW.id_perfil_destinatario;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'El perfil destinatario % no existe.', NEW.id_perfil_destinatario
            USING ERRCODE = 'foreign_key_violation';
    END IF;

    IF v_remitente_perfil_estado <> 'ACTIVO'
       OR v_destinatario_perfil_estado <> 'ACTIVO' THEN
        RAISE EXCEPTION 'Ambos perfiles deben estar activos para enviar una solicitud de conexión.'
            USING ERRCODE = 'check_violation';
    END IF;

    IF v_remitente_usuario_estado <> 'ACTIVO'
       OR v_destinatario_usuario_estado <> 'ACTIVO' THEN
        RAISE EXCEPTION 'Ambos usuarios deben estar activos para enviar una solicitud de conexión.'
            USING ERRCODE = 'check_violation';
    END IF;

    IF v_remitente_usuario = v_destinatario_usuario THEN
        RAISE EXCEPTION 'No se puede enviar una solicitud entre perfiles del mismo usuario.'
            USING ERRCODE = 'check_violation';
    END IF;

    IF TG_OP = 'INSERT' AND EXISTS (
        SELECT 1
        FROM conexion c
        WHERE c.estado = 'ACTIVA'
          AND (
            (c.id_perfil_1 = NEW.id_perfil_remitente
             AND c.id_perfil_2 = NEW.id_perfil_destinatario)
            OR
            (c.id_perfil_1 = NEW.id_perfil_destinatario
             AND c.id_perfil_2 = NEW.id_perfil_remitente)
          )
    ) THEN
        RAISE EXCEPTION 'Ya existe una conexión activa entre los perfiles.'
            USING ERRCODE = 'check_violation';
    END IF;

    IF TG_OP = 'INSERT' THEN
        IF NEW.estado <> 'PENDIENTE' OR NEW.fecha_respuesta IS NOT NULL THEN
            RAISE EXCEPTION 'Una solicitud de conexión nueva debe crearse en estado PENDIENTE.'
                USING ERRCODE = 'check_violation';
        END IF;
    ELSE
        IF NEW.id_perfil_remitente IS DISTINCT FROM OLD.id_perfil_remitente
           OR NEW.id_perfil_destinatario IS DISTINCT FROM OLD.id_perfil_destinatario
           OR NEW.fecha_envio IS DISTINCT FROM OLD.fecha_envio THEN
            RAISE EXCEPTION 'No se pueden modificar los perfiles ni la fecha de envío de una solicitud.'
                USING ERRCODE = 'check_violation';
        END IF;

        IF OLD.estado <> 'PENDIENTE' THEN
            RAISE EXCEPTION 'Sólo se puede gestionar una solicitud pendiente.'
                USING ERRCODE = 'check_violation';
        END IF;

        IF NEW.estado NOT IN ('ACEPTADA', 'RECHAZADA') THEN
            RAISE EXCEPTION 'Estado de solicitud de conexión inválido.'
                USING ERRCODE = 'check_violation';
        END IF;

        IF NEW.fecha_respuesta IS NULL THEN
            NEW.fecha_respuesta := clock_timestamp();
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_validar_solicitud_conexion ON solicitud_conexion;
CREATE TRIGGER trg_validar_solicitud_conexion
    BEFORE INSERT OR UPDATE ON solicitud_conexion
    FOR EACH ROW EXECUTE FUNCTION fn_validar_solicitud_conexion();

CREATE OR REPLACE FUNCTION fn_validar_conexion() RETURNS trigger AS $$
DECLARE
    v_solicitud_estado VARCHAR(20);
    v_solicitud_remitente BIGINT;
    v_solicitud_destinatario BIGINT;
    v_usuario_1 BIGINT;
    v_usuario_2 BIGINT;
    v_perfil_1_estado VARCHAR(50);
    v_perfil_2_estado VARCHAR(50);
    v_usuario_1_estado VARCHAR(20);
    v_usuario_2_estado VARCHAR(20);
BEGIN
    IF TG_OP = 'INSERT' THEN
        SELECT p.id_usuario, p.estado, u.estado
          INTO v_usuario_1, v_perfil_1_estado, v_usuario_1_estado
          FROM perfil p
          JOIN usuario u ON u.id_usuario = p.id_usuario
         WHERE p.id_perfil = NEW.id_perfil_1;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'El perfil % no existe.', NEW.id_perfil_1
                USING ERRCODE = 'foreign_key_violation';
        END IF;

        SELECT p.id_usuario, p.estado, u.estado
          INTO v_usuario_2, v_perfil_2_estado, v_usuario_2_estado
          FROM perfil p
          JOIN usuario u ON u.id_usuario = p.id_usuario
         WHERE p.id_perfil = NEW.id_perfil_2;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'El perfil % no existe.', NEW.id_perfil_2
                USING ERRCODE = 'foreign_key_violation';
        END IF;

        IF v_perfil_1_estado <> 'ACTIVO' OR v_perfil_2_estado <> 'ACTIVO' THEN
            RAISE EXCEPTION 'Ambos perfiles deben estar activos para registrar una conexión.'
                USING ERRCODE = 'check_violation';
        END IF;

        IF v_usuario_1_estado <> 'ACTIVO' OR v_usuario_2_estado <> 'ACTIVO' THEN
            RAISE EXCEPTION 'Ambos usuarios deben estar activos para registrar una conexión.'
                USING ERRCODE = 'check_violation';
        END IF;

        IF v_usuario_1 = v_usuario_2 THEN
            RAISE EXCEPTION 'No se puede conectar dos perfiles del mismo usuario.'
                USING ERRCODE = 'check_violation';
        END IF;

        SELECT s.estado, s.id_perfil_remitente, s.id_perfil_destinatario
          INTO v_solicitud_estado, v_solicitud_remitente, v_solicitud_destinatario
          FROM solicitud_conexion s
         WHERE s.id_solicitud_conexion = NEW.id_solicitud_conexion;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'La solicitud de conexión % no existe.', NEW.id_solicitud_conexion
                USING ERRCODE = 'foreign_key_violation';
        END IF;

        IF v_solicitud_estado <> 'ACEPTADA' THEN
            RAISE EXCEPTION 'La conexión sólo puede originarse en una solicitud aceptada.'
                USING ERRCODE = 'check_violation';
        END IF;

        IF NOT (
            (v_solicitud_remitente = NEW.id_perfil_1 AND v_solicitud_destinatario = NEW.id_perfil_2)
            OR
            (v_solicitud_remitente = NEW.id_perfil_2 AND v_solicitud_destinatario = NEW.id_perfil_1)
        ) THEN
            RAISE EXCEPTION 'La solicitud no corresponde a los perfiles de la conexión.'
                USING ERRCODE = 'check_violation';
        END IF;

        IF NEW.estado <> 'ACTIVA' OR NEW.fecha_fin_conexion IS NOT NULL THEN
            RAISE EXCEPTION 'Una conexión nueva debe crearse ACTIVA.'
                USING ERRCODE = 'check_violation';
        END IF;
    ELSE
        IF NEW.id_perfil_1 IS DISTINCT FROM OLD.id_perfil_1
           OR NEW.id_perfil_2 IS DISTINCT FROM OLD.id_perfil_2
           OR NEW.id_solicitud_conexion IS DISTINCT FROM OLD.id_solicitud_conexion
           OR NEW.fecha_inicio_conexion IS DISTINCT FROM OLD.fecha_inicio_conexion THEN
            RAISE EXCEPTION 'No se pueden modificar los perfiles ni la solicitud de una conexión.'
                USING ERRCODE = 'check_violation';
        END IF;

        IF OLD.estado <> 'ACTIVA' OR NEW.estado <> 'ELIMINADA' THEN
            RAISE EXCEPTION 'Sólo se puede eliminar una conexión activa.'
                USING ERRCODE = 'check_violation';
        END IF;

        IF NEW.fecha_fin_conexion IS NULL THEN
            NEW.fecha_fin_conexion := clock_timestamp();
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_validar_conexion ON conexion;
CREATE TRIGGER trg_validar_conexion
    BEFORE INSERT OR UPDATE ON conexion
    FOR EACH ROW EXECUTE FUNCTION fn_validar_conexion();

INSERT INTO notificacion_tipo (codigo, nombre, categoria, prioridad) VALUES
    ('SOLICITUD_CONEXION_RECIBIDA', 'Solicitud de conexión recibida', 'SOCIAL', 'ALTA'),
    ('SOLICITUD_CONEXION_ACEPTADA', 'Solicitud de conexión aceptada', 'SOCIAL', 'MEDIA'),
    ('SOLICITUD_CONEXION_RECHAZADA', 'Solicitud de conexión rechazada', 'SOCIAL', 'MEDIA'),
    ('CONEXION_ELIMINADA', 'Conexión eliminada', 'SOCIAL', 'MEDIA')
ON CONFLICT (codigo) DO UPDATE
    SET nombre = EXCLUDED.nombre,
        categoria = EXCLUDED.categoria,
        prioridad = EXCLUDED.prioridad,
        activo = true;

-- ============================================================================
-- UC-45 - Auditoria de conexiones
-- Solo se audita el alta y la baja de conexiones, no las solicitudes.
-- ============================================================================

INSERT INTO tipo_evento_auditoria (codigo, nombre, descripcion, modulo) VALUES
    ('CONEXION_CREADA', 'Alta de conexión', 'Creación de una conexión entre dos perfiles', 'CONEXIONES'),
    ('CONEXION_ELIMINADA', 'Baja de conexión', 'Eliminación lógica o física de una conexión', 'CONEXIONES')
ON CONFLICT (codigo) DO UPDATE
    SET nombre = EXCLUDED.nombre,
        descripcion = EXCLUDED.descripcion,
        modulo = EXCLUDED.modulo,
        activo = true;

CREATE OR REPLACE FUNCTION fn_auditar_conexion() RETURNS trigger AS $$
DECLARE
    v_detalle jsonb;
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_detalle := jsonb_build_array(
            jsonb_build_object('campo', 'id_perfil_1', 'nuevo', NEW.id_perfil_1::text),
            jsonb_build_object('campo', 'id_perfil_2', 'nuevo', NEW.id_perfil_2::text),
            jsonb_build_object('campo', 'id_solicitud_conexion', 'nuevo', NEW.id_solicitud_conexion::text),
            jsonb_build_object('campo', 'estado', 'nuevo', NEW.estado),
            jsonb_build_object('campo', 'fecha_inicio_conexion', 'nuevo', NEW.fecha_inicio_conexion::text)
        );
        PERFORM fn_auditoria_registrar(
            'conexion', NEW.id_conexion, 'CONEXION_CREADA', 'INSERT', v_detalle);
        RETURN NEW;
    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.estado = 'ACTIVA' AND NEW.estado = 'ELIMINADA' THEN
            v_detalle := jsonb_build_array(
                jsonb_build_object('campo', 'estado', 'anterior', OLD.estado, 'nuevo', NEW.estado),
                jsonb_build_object('campo', 'fecha_fin_conexion', 'anterior', OLD.fecha_fin_conexion::text, 'nuevo', NEW.fecha_fin_conexion::text)
            );
            PERFORM fn_auditoria_registrar(
                'conexion', NEW.id_conexion, 'CONEXION_ELIMINADA', 'UPDATE', v_detalle);
        END IF;
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        v_detalle := jsonb_build_array(
            jsonb_build_object('campo', 'id_perfil_1', 'anterior', OLD.id_perfil_1::text),
            jsonb_build_object('campo', 'id_perfil_2', 'anterior', OLD.id_perfil_2::text),
            jsonb_build_object('campo', 'id_solicitud_conexion', 'anterior', OLD.id_solicitud_conexion::text),
            jsonb_build_object('campo', 'estado', 'anterior', OLD.estado)
        );
        PERFORM fn_auditoria_registrar(
            'conexion', OLD.id_conexion, 'CONEXION_ELIMINADA', 'DELETE', v_detalle);
        RETURN OLD;
    END IF;

    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_auditar_conexion ON conexion;
CREATE TRIGGER trg_auditar_conexion
    AFTER INSERT OR UPDATE OF estado OR DELETE ON conexion
    FOR EACH ROW EXECUTE FUNCTION fn_auditar_conexion();

-- ============================================================================
-- UC-42 - Enviar mensaje privado
-- Chat 1 a 1 entre perfiles con conexión activa.
-- ============================================================================

CREATE TABLE IF NOT EXISTS conversacion (
    id_conversacion       int8 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_perfil_1           int8 NOT NULL,
    id_perfil_2           int8 NOT NULL,
    fecha_creacion        timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
    fecha_ultimo_mensaje  timestamp,
    CONSTRAINT "PK_conversacion" PRIMARY KEY (id_conversacion),
    CONSTRAINT fk_conversacion_perfil_1
        FOREIGN KEY (id_perfil_1) REFERENCES perfil(id_perfil),
    CONSTRAINT fk_conversacion_perfil_2
        FOREIGN KEY (id_perfil_2) REFERENCES perfil(id_perfil),
    CONSTRAINT chk_conversacion_orden CHECK (id_perfil_1 < id_perfil_2),
    CONSTRAINT "UQ_conversacion_par" UNIQUE (id_perfil_1, id_perfil_2)
);

CREATE INDEX IF NOT EXISTS "IDX_conversacion_perfil_1"
    ON conversacion (id_perfil_1, fecha_ultimo_mensaje DESC);

CREATE INDEX IF NOT EXISTS "IDX_conversacion_perfil_2"
    ON conversacion (id_perfil_2, fecha_ultimo_mensaje DESC);

CREATE TABLE IF NOT EXISTS mensaje (
    id_mensaje        int8 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_conversacion   int8 NOT NULL,
    id_perfil_emisor  int8 NOT NULL,
    contenido         varchar(1000) NOT NULL,
    fecha_envio       timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
    leido             boolean DEFAULT false NOT NULL,
    fecha_lectura     timestamp,
    CONSTRAINT "PK_mensaje" PRIMARY KEY (id_mensaje),
    CONSTRAINT fk_mensaje_conversacion
        FOREIGN KEY (id_conversacion) REFERENCES conversacion(id_conversacion),
    CONSTRAINT fk_mensaje_emisor
        FOREIGN KEY (id_perfil_emisor) REFERENCES perfil(id_perfil),
    CONSTRAINT chk_mensaje_contenido
        CHECK (char_length(btrim(contenido)) BETWEEN 1 AND 1000),
    CONSTRAINT chk_mensaje_lectura CHECK (
        (leido = false AND fecha_lectura IS NULL)
        OR (leido = true AND fecha_lectura IS NOT NULL)
    )
);

CREATE INDEX IF NOT EXISTS "IDX_mensaje_conversacion"
    ON mensaje (id_conversacion, fecha_envio DESC, id_mensaje DESC);

CREATE INDEX IF NOT EXISTS "IDX_mensaje_no_leido"
    ON mensaje (id_conversacion, id_perfil_emisor)
    WHERE leido = false;

CREATE OR REPLACE FUNCTION fn_validar_conversacion() RETURNS trigger AS $$
DECLARE
    v_usuario_1 BIGINT;
    v_usuario_2 BIGINT;
    v_perfil_1_estado VARCHAR(50);
    v_perfil_2_estado VARCHAR(50);
    v_usuario_1_estado VARCHAR(20);
    v_usuario_2_estado VARCHAR(20);
BEGIN
    IF TG_OP = 'INSERT' THEN
        SELECT p.id_usuario, p.estado, u.estado
          INTO v_usuario_1, v_perfil_1_estado, v_usuario_1_estado
          FROM perfil p
          JOIN usuario u ON u.id_usuario = p.id_usuario
         WHERE p.id_perfil = NEW.id_perfil_1;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'El perfil % no existe.', NEW.id_perfil_1
                USING ERRCODE = 'foreign_key_violation';
        END IF;

        SELECT p.id_usuario, p.estado, u.estado
          INTO v_usuario_2, v_perfil_2_estado, v_usuario_2_estado
          FROM perfil p
          JOIN usuario u ON u.id_usuario = p.id_usuario
         WHERE p.id_perfil = NEW.id_perfil_2;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'El perfil % no existe.', NEW.id_perfil_2
                USING ERRCODE = 'foreign_key_violation';
        END IF;

        IF v_usuario_1 = v_usuario_2 THEN
            RAISE EXCEPTION 'No se puede crear una conversación entre perfiles del mismo usuario.'
                USING ERRCODE = 'check_violation';
        END IF;

        IF v_perfil_1_estado <> 'ACTIVO' OR v_perfil_2_estado <> 'ACTIVO'
           OR v_usuario_1_estado <> 'ACTIVO' OR v_usuario_2_estado <> 'ACTIVO' THEN
            RAISE EXCEPTION 'Ambos perfiles y usuarios deben estar activos para iniciar una conversación.'
                USING ERRCODE = 'check_violation';
        END IF;

        IF NOT EXISTS (
            SELECT 1
              FROM conexion c
             WHERE c.estado = 'ACTIVA'
               AND (
                   (c.id_perfil_1 = NEW.id_perfil_1 AND c.id_perfil_2 = NEW.id_perfil_2)
                   OR
                   (c.id_perfil_1 = NEW.id_perfil_2 AND c.id_perfil_2 = NEW.id_perfil_1)
               )
        ) THEN
            RAISE EXCEPTION 'Los perfiles deben tener una conexión activa para chatear.'
                USING ERRCODE = 'check_violation';
        END IF;
    ELSE
        IF NEW.id_perfil_1 IS DISTINCT FROM OLD.id_perfil_1
           OR NEW.id_perfil_2 IS DISTINCT FROM OLD.id_perfil_2
           OR NEW.fecha_creacion IS DISTINCT FROM OLD.fecha_creacion THEN
            RAISE EXCEPTION 'No se pueden modificar los participantes ni la fecha de creación de una conversación.'
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_validar_conversacion ON conversacion;
CREATE TRIGGER trg_validar_conversacion
    BEFORE INSERT OR UPDATE ON conversacion
    FOR EACH ROW EXECUTE FUNCTION fn_validar_conversacion();

CREATE OR REPLACE FUNCTION fn_validar_mensaje() RETURNS trigger AS $$
DECLARE
    v_perfil_1 BIGINT;
    v_perfil_2 BIGINT;
    v_perfil_emisor_estado VARCHAR(50);
    v_usuario_emisor_estado VARCHAR(20);
    v_perfil_receptor_estado VARCHAR(50);
    v_usuario_receptor_estado VARCHAR(20);
    v_perfil_receptor BIGINT;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Los mensajes no se pueden eliminar.'
            USING ERRCODE = 'check_violation';
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF NEW.id_conversacion IS DISTINCT FROM OLD.id_conversacion
           OR NEW.id_perfil_emisor IS DISTINCT FROM OLD.id_perfil_emisor
           OR NEW.contenido IS DISTINCT FROM OLD.contenido
           OR NEW.fecha_envio IS DISTINCT FROM OLD.fecha_envio THEN
            RAISE EXCEPTION 'Solo se puede modificar el estado de lectura de un mensaje.'
                USING ERRCODE = 'check_violation';
        END IF;

        IF OLD.leido = true AND NEW.leido = false THEN
            RAISE EXCEPTION 'Un mensaje leído no puede volver a no leído.'
                USING ERRCODE = 'check_violation';
        END IF;

        RETURN NEW;
    END IF;

    SELECT c.id_perfil_1, c.id_perfil_2
      INTO v_perfil_1, v_perfil_2
      FROM conversacion c
     WHERE c.id_conversacion = NEW.id_conversacion;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La conversación % no existe.', NEW.id_conversacion
            USING ERRCODE = 'foreign_key_violation';
    END IF;

    IF NEW.id_perfil_emisor <> v_perfil_1
       AND NEW.id_perfil_emisor <> v_perfil_2 THEN
        RAISE EXCEPTION 'El emisor no participa de la conversación.'
            USING ERRCODE = 'check_violation';
    END IF;

    IF NOT EXISTS (
        SELECT 1
          FROM conexion c
         WHERE c.estado = 'ACTIVA'
           AND (
               (c.id_perfil_1 = v_perfil_1 AND c.id_perfil_2 = v_perfil_2)
               OR
               (c.id_perfil_1 = v_perfil_2 AND c.id_perfil_2 = v_perfil_1)
           )
    ) THEN
        RAISE EXCEPTION 'La conexión entre los perfiles no está activa.'
            USING ERRCODE = 'check_violation';
    END IF;

    SELECT p.estado, u.estado
      INTO v_perfil_emisor_estado, v_usuario_emisor_estado
      FROM perfil p
      JOIN usuario u ON u.id_usuario = p.id_usuario
     WHERE p.id_perfil = NEW.id_perfil_emisor;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'El perfil emisor % no existe.', NEW.id_perfil_emisor
            USING ERRCODE = 'foreign_key_violation';
    END IF;

    v_perfil_receptor := CASE
        WHEN NEW.id_perfil_emisor = v_perfil_1 THEN v_perfil_2
        ELSE v_perfil_1
    END;

    SELECT p.estado, u.estado
      INTO v_perfil_receptor_estado, v_usuario_receptor_estado
      FROM perfil p
      JOIN usuario u ON u.id_usuario = p.id_usuario
     WHERE p.id_perfil = v_perfil_receptor;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'El perfil receptor % no existe.', v_perfil_receptor
            USING ERRCODE = 'foreign_key_violation';
    END IF;

    IF v_perfil_emisor_estado <> 'ACTIVO' OR v_usuario_emisor_estado <> 'ACTIVO'
       OR v_perfil_receptor_estado <> 'ACTIVO' OR v_usuario_receptor_estado <> 'ACTIVO' THEN
        RAISE EXCEPTION 'Ambos perfiles y usuarios deben estar activos para enviar mensajes.'
            USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.leido <> false OR NEW.fecha_lectura IS NOT NULL THEN
        RAISE EXCEPTION 'Un mensaje nuevo debe crearse no leído.'
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_validar_mensaje ON mensaje;
CREATE TRIGGER trg_validar_mensaje
    BEFORE INSERT OR UPDATE OR DELETE ON mensaje
    FOR EACH ROW EXECUTE FUNCTION fn_validar_mensaje();

CREATE OR REPLACE FUNCTION fn_actualizar_ultimo_mensaje() RETURNS trigger AS $$
BEGIN
    UPDATE conversacion
       SET fecha_ultimo_mensaje = GREATEST(
               COALESCE(fecha_ultimo_mensaje, NEW.fecha_envio),
               NEW.fecha_envio)
     WHERE id_conversacion = NEW.id_conversacion;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_actualizar_ultimo_mensaje ON mensaje;
CREATE TRIGGER trg_actualizar_ultimo_mensaje
    AFTER INSERT ON mensaje
    FOR EACH ROW EXECUTE FUNCTION fn_actualizar_ultimo_mensaje();

