-- UC-41 - Enviar mensaje a chat grupal
-- Chat único por proyecto. Los mensajes son inmutables.

CREATE TABLE IF NOT EXISTS mensaje_proyecto (
    id_mensaje_proyecto  int8 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_proyecto          int8 NOT NULL,
    id_perfil_emisor     int8 NOT NULL,
    contenido            varchar(1000) NOT NULL,
    fecha_envio          timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "PK_mensaje_proyecto" PRIMARY KEY (id_mensaje_proyecto),
    CONSTRAINT fk_mensaje_proyecto_proyecto
        FOREIGN KEY (id_proyecto) REFERENCES proyecto(id_proyecto),
    CONSTRAINT fk_mensaje_proyecto_emisor
        FOREIGN KEY (id_perfil_emisor) REFERENCES perfil(id_perfil),
    CONSTRAINT chk_mensaje_proyecto_contenido
        CHECK (char_length(btrim(contenido)) BETWEEN 1 AND 1000)
);

CREATE INDEX IF NOT EXISTS "IDX_mensaje_proyecto_historial"
    ON mensaje_proyecto (id_proyecto, fecha_envio DESC, id_mensaje_proyecto DESC);

CREATE OR REPLACE FUNCTION fn_validar_mensaje_proyecto() RETURNS trigger AS $$
DECLARE
    v_estado_proyecto varchar(50);
    v_perfil_estado varchar(50);
    v_usuario_estado varchar(20);
    v_es_miembro boolean;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Los mensajes del chat grupal no se pueden eliminar.'
            USING ERRCODE = 'check_violation';
    END IF;

    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'Los mensajes del chat grupal son inmutables.'
            USING ERRCODE = 'check_violation';
    END IF;

    SELECT p.estado
      INTO v_estado_proyecto
      FROM proyecto p
     WHERE p.id_proyecto = NEW.id_proyecto;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'El proyecto % no existe.', NEW.id_proyecto
            USING ERRCODE = 'foreign_key_violation';
    END IF;

    IF v_estado_proyecto NOT IN ('PUBLICADO', 'CONFIRMADO') THEN
        RAISE EXCEPTION 'El proyecto no admite mensajes en su estado actual.'
            USING ERRCODE = 'check_violation';
    END IF;

    SELECT p.estado, u.estado, true
      INTO v_perfil_estado, v_usuario_estado, v_es_miembro
      FROM miembros_proyecto mp
      JOIN perfil p ON p.id_perfil = mp.id_perfil
      JOIN usuario u ON u.id_usuario = p.id_usuario
     WHERE mp.id_proyecto = NEW.id_proyecto
       AND mp.id_perfil = NEW.id_perfil_emisor
       AND mp.estado_participacion = 'ACTIVO';

    IF NOT FOUND OR v_es_miembro IS DISTINCT FROM true THEN
        RAISE EXCEPTION 'El emisor no es un participante activo del proyecto.'
            USING ERRCODE = 'check_violation';
    END IF;

    IF v_perfil_estado <> 'ACTIVO' OR v_usuario_estado <> 'ACTIVO' THEN
        RAISE EXCEPTION 'El perfil y el usuario del emisor deben estar activos.'
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_validar_mensaje_proyecto ON mensaje_proyecto;
CREATE TRIGGER trg_validar_mensaje_proyecto
    BEFORE INSERT OR UPDATE OR DELETE ON mensaje_proyecto
    FOR EACH ROW EXECUTE FUNCTION fn_validar_mensaje_proyecto();

